INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-10', 'doc-14-nist-sp-800-53', '', 376, 'Discussion: Learning mechanisms include Bayesian filters that respond to user inputs that identify specific traffic as spam or legitimate by updating algorithm parameters and thereby more accurately separating types of traffic.', 'kb-doc-14-nist-sp-800-53-p376-10', 0, 31, '14-nist-sp-800-53', 'retrieved', '314C8CED70BBF557407148AB57255B682392641F0CBA8A0044095CEB97C6E0CB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
