INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-13', 'doc-14-nist-sp-800-53', '', 376, 'SI-9 INFORMATION INPUT RESTRICTIONS [Withdrawn: Incorporated into AC-2, AC-3, AC-5, and AC-6.] SI-10 INFORMATION INPUT VALIDATION Control: Check the validity of the following information inputs: [Assignment: organization- defined information inputs to the system].', 'kb-doc-14-nist-sp-800-53-p376-13', 0, 33, '14-nist-sp-800-53', 'retrieved', '18ED2EFA00841CB6FB3013846CC363993AAE6AC1782A4686D8B3376165CBA2D9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-14', 'doc-14-nist-sp-800-53', '', 376, 'Discussion: Checking the valid syntax and semantics of system inputs— including character set, length, numerical range, and acceptable values— verifies that inputs match specified definitions for format and content. For example, if the organization specifies that numerical values between 1-100 are the only acceptable inputs for a field in a given application, inputs of “387,” “abc,” or “%K%” are invalid inputs and are not accepted as input to the system. Valid inputs are likely to vary from field to field within a software application. Applications typically follow well-defined protocols that use structured messages (i.e., commands or queries) to communicate between software modules or system components. Structured messages can contain raw or unstructured data interspersed with metadata or control information. If software applications use attacker- supplied inputs to construct structured messages without properly encoding such messages, then the attacker could insert malicious commands or special characters that can cause the data', 'kb-doc-14-nist-sp-800-53-p376-14', 0, 150, '14-nist-sp-800-53', 'retrieved', '6B6BC310580352BC6B0F6B29D8E0D8C61EB90EF7532877EB27D5D0506216973C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-1', 'doc-14-nist-sp-800-53', '', 377, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 350 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p377-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '79D12BCEE998A62D8C28656D251B93796FE045D070C25E9D848F4B70F785FA73', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-2', 'doc-14-nist-sp-800-53', '', 377, 'to be interpreted as control information or metadata. Consequently, the module or component that receives the corrupted output will perform the wrong operations or otherwise interpret the data incorrectly. Prescreening inputs prior to passing them to interpreters prevents the content from being unintentionally interpreted as commands. Input validation ensures accurate and correct inputs and prevents attacks such as cross-site scripting and a variety of injection attacks.', 'kb-doc-14-nist-sp-800-53-p377-2', 0, 66, '14-nist-sp-800-53', 'retrieved', 'B66B5A7DAA04C0C085D0C7906126C0EC813BE7B009CD422680C46A70D747FF04', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-4', 'doc-14-nist-sp-800-53', '', 377, 'Control Enhancements: (1) INFORMATION INPUT VALIDATION | MANUAL OVERRIDE CAPABILITY (a) Provide a manual override capability for input validation of the following information inputs: [Assignment: organization-defined inputs defined in the base control (SI-10)]; (b) Restrict the use of the manual override capability to only [Assignment: organization- defined authorized individuals]; and (c) Audit the use of the manual override capability.', 'kb-doc-14-nist-sp-800-53-p377-4', 0, 59, '14-nist-sp-800-53', 'retrieved', 'D03CD3D8CBA5A0FAF736D9F920E341EFEB7F8DCE9B1931DAB2F6D983F1BB1941', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-5', 'doc-14-nist-sp-800-53', '', 377, 'Discussion: In certain situations, such as during events that are defined in contingency plans, a manual override capability for input validation may be needed. Manual overrides are used only in limited circumstances and with the inputs defined by the organization.', 'kb-doc-14-nist-sp-800-53-p377-5', 0, 40, '14-nist-sp-800-53', 'retrieved', '08EB00A00CD5A10A1097204F7270EDA125AA89E0A7737C91B82E0B91547773D4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-7', 'doc-14-nist-sp-800-53', '', 377, '(2) INFORMATION INPUT VALIDATION | REVIEW AND RESOLVE ERRORS Review and resolve input validation errors within [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p377-7', 0, 20, '14-nist-sp-800-53', 'retrieved', '9E65A19DF68BB09808F2976F0F8A1BA67915EFE82B68C276CC3D960637D07D63', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-8', 'doc-14-nist-sp-800-53', '', 377, 'Discussion: Resolution of input validation errors includes correcting systemic causes of errors and resubmitting transactions with corrected input. Input validation errors are those related to the information inputs defined by the organization in the base control (SI-10).', 'kb-doc-14-nist-sp-800-53-p377-8', 0, 37, '14-nist-sp-800-53', 'retrieved', '9203AF7D2B01ED46D71121901B1E8F5B116D61D1FF8D436C507F8E93E906F982', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-10', 'doc-14-nist-sp-800-53', '', 377, '(3) INFORMATION INPUT VALIDATION | PREDICTABLE BEHAVIOR Verify that the system behaves in a predictable and documented manner when invalid inputs are received.', 'kb-doc-14-nist-sp-800-53-p377-10', 0, 23, '14-nist-sp-800-53', 'retrieved', '89090C18231BD51194D9FD67FF05A2563252004C7759D821605E0174C873961E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-11', 'doc-14-nist-sp-800-53', '', 377, 'Discussion: A common vulnerability in organizational systems is unpredictable behavior when invalid inputs are received. Verification of system predictability helps ensure that the system behaves as expected when invalid inputs are received. This occurs by specifying system responses that allow the system to transition to known states without adverse, unintended side effects. The invalid inputs are those related to the information inputs defined by the organization in the base control (SI-10).', 'kb-doc-14-nist-sp-800-53-p377-11', 0, 71, '14-nist-sp-800-53', 'retrieved', 'A3D304FB351B807D9258D0CF8FE03D9AD3946D3FA272905AE4A77D29F6B58578', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-13', 'doc-14-nist-sp-800-53', '', 377, '(4) INFORMATION INPUT VALIDATION | TIMING INTERACTIONS Account for timing interactions among system components in determining appropriate responses for invalid inputs.', 'kb-doc-14-nist-sp-800-53-p377-13', 0, 21, '14-nist-sp-800-53', 'retrieved', '34806D435B98A5641EFB67E3C25C77B361DDA425573CAB74FAFA8CEE81485912', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p377-14', 'doc-14-nist-sp-800-53', '', 377, 'Discussion: In addressing invalid system inputs received across protocol interfaces, timing interactions become relevant, where one protocol needs to consider the impact of the error response on other protocols in the protocol stack. For example, 802.11 standard wireless network protocols do not interact well with Transmission Control Protocols (TCP) when packets are dropped (which could be due to invalid packet input). TCP assumes packet losses are due to congestion, while packets lost over 802.11 links are typically dropped due to noise or collisions on the link. If TCP makes a congestion response, it takes the wrong action in response to a collision event. Adversaries may be able to use what appear to be acceptable individual behaviors of the protocols in concert to achieve adverse effects through suitable', 'kb-doc-14-nist-sp-800-53-p377-14', 0, 127, '14-nist-sp-800-53', 'retrieved', '597CD7D9BF6674BAA15B98351A229D309252217B3463CB2EE02FD78A1BA47C0C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p378-1', 'doc-14-nist-sp-800-53', '', 378, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 351 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p378-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D3EFDA36C6340EF72F3E19A08FDE5CF16DEF1ED796D72265DF4493C33FDA93D7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
