VALUES ('doc-14-nist-sp-800-53-p378-2', 'doc-14-nist-sp-800-53', '', 378, 'construction of invalid input. The invalid inputs are those related to the information inputs defined by the organization in the base control (SI-10).', 'kb-doc-14-nist-sp-800-53-p378-2', 0, 23, '14-nist-sp-800-53', 'retrieved', 'C9772ABA6CCB067C36272A4E189E2F0EB30E03A710C588CE19AF63EF7DCEE91F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
