VALUES ('doc-14-nist-sp-800-53-p379-1', 'doc-14-nist-sp-800-53', '', 379, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 352 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p379-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'AB14A2068AD614714433EB8166921135EBF51F6301D65FC0138C2FB511B1EA6E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
