VALUES ('doc-14-nist-sp-800-53-p379-5', 'doc-14-nist-sp-800-53', '', 379, 'Related Controls: All XX-1 Controls, AC-16, AU-5, AU-11, CA-2, CA-3, CA-5, CA-6, CA-7, CA-9, CM- 5, CM-9, CP-2, IR-8, MP-2, MP-3, MP-4, MP-6, PL-2, PL-4, PM-4, PM-8, PM-9, PS-2, PS-6, PT-2, PT- 3, RA-2, RA-3, SA-5, SA-8, SR-2.', 'kb-doc-14-nist-sp-800-53-p379-5', 0, 38, '14-nist-sp-800-53', 'retrieved', 'A5A74DBFA3B33D604FBD7F81B6AC5CB0CAB8B7BA94DE20A2A5B561BC4F7DF715', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
