VALUES ('doc-14-nist-sp-800-53-p381-1', 'doc-14-nist-sp-800-53', '', 381, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 354 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p381-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '79F5B4A483980FE5F17C9646D3CC68C98C8DA74F01EA1DEF503997A242EED72D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p381-2', 'doc-14-nist-sp-800-53', '', 381, '(a) Ensure that the standby components are successfully and transparently installed within [Assignment: organization-defined time period]; and (b) [Selection (one or more): Activate [Assignment: organization-defined alarm]; Automatically shut down the system; [Assignment: organization-defined action]].', 'kb-doc-14-nist-sp-800-53-p381-2', 0, 34, '14-nist-sp-800-53', 'retrieved', 'AA0B191083D825195EA7578E04DB6D93DF6BCE3D1CA6B77C8060799AC1C1C9E8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
