INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p381-3', 'doc-14-nist-sp-800-53', '', 381, 'Discussion: Automatic or manual transfer of components from standby to active mode can occur upon the detection of component failures.', 'kb-doc-14-nist-sp-800-53-p381-3', 0, 20, '14-nist-sp-800-53', 'retrieved', 'C27B9EB497B8618AA784BC7FD39EEF416099841AA7BB80ED31E47A14D79F2B4D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
