VALUES ('doc-14-nist-sp-800-53-p382-1', 'doc-14-nist-sp-800-53', '', 382, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 355 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p382-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '262F720D5AAFFE024110BD3DFE610427F7B4DC2CAAC693F49F140B242BE477B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
