INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-2', 'doc-14-nist-sp-800-53', '', 382, 'Obtain software and data employed during system component and service refreshes from the following trusted sources: [Assignment: organization-defined trusted sources].', 'kb-doc-14-nist-sp-800-53-p382-2', 0, 20, '14-nist-sp-800-53', 'retrieved', '0F40F4F530E07002720C7DC1B78A0205381099BCCBFB4B61E7EF5DEA7E838A5F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
