INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-3', 'doc-14-nist-sp-800-53', '', 382, 'Discussion: Trusted sources include software and data from write-once, read-only media or from selected offline secure storage facilities.', 'kb-doc-14-nist-sp-800-53-p382-3', 0, 18, '14-nist-sp-800-53', 'retrieved', 'CDCEB3A22E8836259F9C33E8429CA7683405CB9EA96D8018075695F423DC6655', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
