INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-5', 'doc-14-nist-sp-800-53', '', 382, '(2) NON-PERSISTENCE | NON-PERSISTENT INFORMATION (a) [Selection: Refresh [Assignment: organization-defined information] [Assignment: organization-defined frequency]; Generate [Assignment: organization-defined information] on demand]; and (b) Delete information when no longer needed.', 'kb-doc-14-nist-sp-800-53-p382-5', 0, 28, '14-nist-sp-800-53', 'retrieved', '34197CDBDA6F1E9A638E5A97F386313005CF27A9F3C15885EE7834D2EB7E9BCC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-6', 'doc-14-nist-sp-800-53', '', 382, 'Discussion: Retaining information longer than is needed makes the information a potential target for advanced adversaries searching for high value assets to compromise through unauthorized disclosure, unauthorized modification, or exfiltration. For system-related information, unnecessary retention provides advanced adversaries information that can assist in their reconnaissance and lateral movement through the system.', 'kb-doc-14-nist-sp-800-53-p382-6', 0, 51, '14-nist-sp-800-53', 'retrieved', '0BE2A369100C505573E5FED387518C6CEDCC7821AD1B8EBB5FC3C25542CFDDB6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-8', 'doc-14-nist-sp-800-53', '', 382, '(3) NON-PERSISTENCE | NON-PERSISTENT CONNECTIVITY Establish connections to the system on demand and terminate connections after [Selection: completion of a request; a period of non-use].', 'kb-doc-14-nist-sp-800-53-p382-8', 0, 25, '14-nist-sp-800-53', 'retrieved', 'B5F65EBA091B26EB274EB7C745EC40E857DDE73476F766D12BA1F14570C7C769', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-9', 'doc-14-nist-sp-800-53', '', 382, 'Discussion: Persistent connections to systems can provide advanced adversaries with paths to move laterally through systems and potentially position themselves closer to high value assets. Limiting the availability of such connections impedes the adversary’s ability to move freely through organizational systems.', 'kb-doc-14-nist-sp-800-53-p382-9', 0, 41, '14-nist-sp-800-53', 'retrieved', '1DA6FC7C70DDF7F1773FF7533E93D9A386A1E86E4F700243020FE920D1777AE8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-12', 'doc-14-nist-sp-800-53', '', 382, 'SI-15 INFORMATION OUTPUT FILTERING Control: Validate information output from the following software programs and/or applications to ensure that the information is consistent with the expected content: [Assignment: organization-defined software programs and/or applications].', 'kb-doc-14-nist-sp-800-53-p382-12', 0, 32, '14-nist-sp-800-53', 'retrieved', '0A11552512EC49C2573DA7247854DC352ED6EB300158F11DD80C51027FE11E6F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-13', 'doc-14-nist-sp-800-53', '', 382, 'Discussion: Certain types of attacks, including SQL injections, produce output results that are unexpected or inconsistent with the output results that would be expected from software programs or applications. Information output filtering focuses on detecting extraneous content, preventing such extraneous content from being displayed, and then alerting monitoring tools that anomalous behavior has been discovered.', 'kb-doc-14-nist-sp-800-53-p382-13', 0, 55, '14-nist-sp-800-53', 'retrieved', '76BB5633678AAADCC6F311984471AE4C98C4EDBCA90D8F0677F6143A8C373224', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-17', 'doc-14-nist-sp-800-53', '', 382, 'SI-16 MEMORY PROTECTION Control: Implement the following controls to protect the system memory from unauthorized code execution: [Assignment: organization-defined controls].', 'kb-doc-14-nist-sp-800-53-p382-17', 0, 20, '14-nist-sp-800-53', 'retrieved', '6AE250C22D946E279E937E07657D6C8FB4FA5C4E2AC6E73491F0EB249F395384', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p382-18', 'doc-14-nist-sp-800-53', '', 382, 'Discussion: Some adversaries launch attacks with the intent of executing code in non-executable regions of memory or in memory locations that are prohibited. Controls employed to protect memory include data execution prevention and address space layout randomization. Data', 'kb-doc-14-nist-sp-800-53-p382-18', 0, 38, '14-nist-sp-800-53', 'retrieved', '748B53822D29DA5BC5028F6DA4966ACE42A23E4171345225E3F22A73F4C86970', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
