VALUES ('doc-14-nist-sp-800-53-p383-1', 'doc-14-nist-sp-800-53', '', 383, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 356 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p383-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '05F88D6A009A33A892F9CA263C86D8EDBA07C9699773DD926E81521CAEA29E9A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
