INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p383-2', 'doc-14-nist-sp-800-53', '', 383, 'execution prevention controls can either be hardware-enforced or software-enforced with hardware enforcement providing the greater strength of mechanism.', 'kb-doc-14-nist-sp-800-53-p383-2', 0, 18, '14-nist-sp-800-53', 'retrieved', 'F4970C485BB7EDE7B31AE7D12FF1BA769A4D2DCD1EDFC3DC56837235C6E855A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
