VALUES ('doc-14-nist-sp-800-53-p384-1', 'doc-14-nist-sp-800-53', '', 384, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 357 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p384-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '38214821D01D5018921692D3C3317D30B0C29AC3BF32D9738A9F96A78681FDF7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
