INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p384-2', 'doc-14-nist-sp-800-53', '', 384, 'Correct or delete personally identifiable information that is inaccurate or outdated, incorrectly determined regarding impact, or incorrectly de-identified using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p384-2', 0, 23, '14-nist-sp-800-53', 'retrieved', '981D1426E267DCA98ED07DAC05278005209725406FE94C209641B8E28D691B3D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
