INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p384-7', 'doc-14-nist-sp-800-53', '', 384, 'Discussion: Data tagging personally identifiable information includes tags that note processing permissions, authority to process, de-identification, impact level, information life cycle stage, and retention or last updated dates. Employing data tags for personally identifiable information can support the use of automation tools to correct or delete relevant personally identifiable information.', 'kb-doc-14-nist-sp-800-53-p384-7', 0, 50, '14-nist-sp-800-53', 'retrieved', '44A7630952E95C824FE986EF4CBFF3BE53C44CBAE442553C19C8036B911CCD86', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
