INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p384-9', 'doc-14-nist-sp-800-53', '', 384, '(3) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | COLLECTION Collect personally identifiable information directly from the individual.', 'kb-doc-14-nist-sp-800-53-p384-9', 0, 16, '14-nist-sp-800-53', 'retrieved', '7808A13FF65317426133B5577087B04C6129F27A273BA76C76F7EBD21FC01615', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
