VALUES ('doc-14-nist-sp-800-53-p384-12', 'doc-14-nist-sp-800-53', '', 384, '(4) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | INDIVIDUAL REQUESTS Correct or delete personally identifiable information upon request by individuals or their designated representatives.', 'kb-doc-14-nist-sp-800-53-p384-12', 0, 23, '14-nist-sp-800-53', 'retrieved', '36534566982E514FFA514F63AB7B3AD7D4FD92B4ED64B94D39B139AB9442D07D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
