INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p384-13', 'doc-14-nist-sp-800-53', '', 384, 'Discussion: Inaccurate personally identifiable information maintained by organizations may cause problems for individuals, especially in those business functions where inaccurate information may result in inappropriate decisions or the denial of benefits and services to individuals. Even correct information, in certain circumstances, can cause problems for', 'kb-doc-14-nist-sp-800-53-p384-13', 0, 45, '14-nist-sp-800-53', 'retrieved', '02A0D1FC51FBFDAFC09190E07D0153DF7219B28B3610AC72AE7713E8427DFCF0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
