VALUES ('doc-14-nist-sp-800-53-p385-2', 'doc-14-nist-sp-800-53', '', 385, 'individuals that outweigh the benefits of an organization maintaining the information.', 'kb-doc-14-nist-sp-800-53-p385-2', 0, 11, '14-nist-sp-800-53', 'retrieved', '217978292A3657B125D872EDB6382FA281674B8B5794E047A68F4F67EAD13930', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
