INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p385-3', 'doc-14-nist-sp-800-53', '', 385, 'Organizations use discretion when determining if personally identifiable information is to be corrected or deleted based on the scope of requests, the changes sought, the impact of the changes, and laws, regulations, and policies. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding appropriate instances of correction or deletion.', 'kb-doc-14-nist-sp-800-53-p385-3', 0, 54, '14-nist-sp-800-53', 'retrieved', 'D21F0EDACF28BEB0BAB10F45A2696FC06D6493D79DF9DB5F123DB47350608DC3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
