INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p385-5', 'doc-14-nist-sp-800-53', '', 385, '(5) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | NOTICE OF CORRECTION OR DELETION Notify [Assignment: organization-defined recipients of personally identifiable information] and individuals that the personally identifiable information has been corrected or deleted.', 'kb-doc-14-nist-sp-800-53-p385-5', 0, 32, '14-nist-sp-800-53', 'retrieved', 'EF61DE1962DD46D9410143FF6C9F89BE066B1E8FF4BABC1F9A7F42B751C75DD7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
