INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p385-6', 'doc-14-nist-sp-800-53', '', 385, 'Discussion: When personally identifiable information is corrected or deleted, organizations take steps to ensure that all authorized recipients of such information, and the individual with whom the information is associated or their designated representatives, are informed of the corrected or deleted information.', 'kb-doc-14-nist-sp-800-53-p385-6', 0, 42, '14-nist-sp-800-53', 'retrieved', '4CE9F6CFB921EA5F5A0A49AB1B8B10C1640941A56B67E5024476A5580DC1CBF1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
