INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p385-9', 'doc-14-nist-sp-800-53', '', 385, 'SI-19 DE-IDENTIFICATION Control: a. Remove the following elements of personally identifiable information from datasets: [Assignment: organization-defined elements of personally identifiable information]; and b. Evaluate [Assignment: organization-defined frequency] for effectiveness of de-identification.', 'kb-doc-14-nist-sp-800-53-p385-9', 0, 31, '14-nist-sp-800-53', 'retrieved', 'BE041E01E5B1A9C637D838BA9CC7C46BC2B3F51650E4AAFC736A03F12D96BA90', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
