INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p385-10', 'doc-14-nist-sp-800-53', '', 385, 'Discussion: De-identification is the general term for the process of removing the association between a set of identifying data and the data subject. Many datasets contain information about individuals that can be used to distinguish or trace an individual’s identity, such as name, social security number, date and place of birth, mother’s maiden name, or biometric records. Datasets may also contain other information that is linked or linkable to an individual, such as medical, educational, financial, and employment information. Personally identifiable information is removed from datasets by trained individuals when such information is not (or no longer) necessary to satisfy the requirements envisioned for the data. For example, if the dataset is only used to produce aggregate statistics, the identifiers that are not needed for producing those statistics are removed. Removing identifiers improves privacy protection since information that is removed cannot be inadvertently disclosed or improperly used.', 'kb-doc-14-nist-sp-800-53-p385-10', 0, 147, '14-nist-sp-800-53', 'retrieved', 'E1F92C9D66B36B9A7191C5F43D839BB6111AD08B5C10894264DBA8A6B5FD0BEB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p385-11', 'doc-14-nist-sp-800-53', '', 385, 'Organizations may be subject to specific de-identification definitions or methods under applicable laws, regulations, or policies.', 'kb-doc-14-nist-sp-800-53-p385-11', 0, 16, '14-nist-sp-800-53', 'retrieved', 'DEE3009F1353223CB3C7FBD87694829E97B3B84AA9E2532C11E2B48337B8B8CD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
