VALUES ('doc-14-nist-sp-800-53-p385-14', 'doc-14-nist-sp-800-53', '', 385, 'Control Enhancements: (1) DE-IDENTIFICATION | COLLECTION De-identify the dataset upon collection by not collecting personally identifiable information.', 'kb-doc-14-nist-sp-800-53-p385-14', 0, 17, '14-nist-sp-800-53', 'retrieved', 'F5833A8C41BC15A22034C73E06397BACCE12C6F67EAB353C787B6FACC55A4231', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
