INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-2', 'doc-14-nist-sp-800-53', '', 386, 'data elements that contain the personally identifiable information. For example, if an organization does not intend to use the social security number of an applicant, then application forms do not ask for a social security number.', 'kb-doc-14-nist-sp-800-53-p386-2', 0, 36, '14-nist-sp-800-53', 'retrieved', 'AAE0B5029E3389697486644A0F58EBC29CE3989163B3086CEEB0746792232CF7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
