INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-4', 'doc-14-nist-sp-800-53', '', 386, '(2) DE-IDENTIFICATION | ARCHIVING Prohibit archiving of personally identifiable information elements if those elements in a dataset will not be needed after the dataset is archived.', 'kb-doc-14-nist-sp-800-53-p386-4', 0, 26, '14-nist-sp-800-53', 'retrieved', '6AC392E1FA935DF78D04015AB22D5B1A5834451B071B23B0D12DE8D101BE8915', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-5', 'doc-14-nist-sp-800-53', '', 386, 'Discussion: Datasets can be archived for many reasons. The envisioned purposes for the archived dataset are specified, and if personally identifiable information elements are not required, the elements are not archived. For example, social security numbers may have been collected for record linkage, but the archived dataset may include the required elements from the linked records. In this case, it is not necessary to archive the social security numbers.', 'kb-doc-14-nist-sp-800-53-p386-5', 0, 69, '14-nist-sp-800-53', 'retrieved', '974B20AA1DAFA987291AA64FAD5F0ADEC9923D6120B3B44AE464D31F8FBB5F7E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-7', 'doc-14-nist-sp-800-53', '', 386, '(3) DE-IDENTIFICATION | RELEASE Remove personally identifiable information elements from a dataset prior to its release if those elements in the dataset do not need to be part of the data release.', 'kb-doc-14-nist-sp-800-53-p386-7', 0, 32, '14-nist-sp-800-53', 'retrieved', 'D09500B6E5B261610277233D9B80E653D401643FE499D76E0CF7C6DD5DE737CA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-8', 'doc-14-nist-sp-800-53', '', 386, 'Discussion: Prior to releasing a dataset, a data custodian considers the intended uses of the dataset and determines if it is necessary to release personally identifiable information. If the personally identifiable information is not necessary, the information can be removed using de-identification techniques.', 'kb-doc-14-nist-sp-800-53-p386-8', 0, 43, '14-nist-sp-800-53', 'retrieved', '5ED2E0D23A339E17776FDCAFABD2AF7C1EA605A6C34EDBDA73CDF76F599CB66A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-10', 'doc-14-nist-sp-800-53', '', 386, '(4) DE-IDENTIFICATION | REMOVAL, MASKING, ENCRYPTION, HASHING, OR REPLACEMENT OF DIRECT IDENTIFIERS Remove, mask, encrypt, hash, or replace direct identifiers in a dataset.', 'kb-doc-14-nist-sp-800-53-p386-10', 0, 23, '14-nist-sp-800-53', 'retrieved', '0B1909B12AD53DFD1B3B514CA2E96944EF950AD412D3AFD60AB1A140E3889C70', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-11', 'doc-14-nist-sp-800-53', '', 386, 'Discussion: There are many possible processes for removing direct identifiers from a dataset. Columns in a dataset that contain a direct identifier can be removed. In masking, the direct identifier is transformed into a repeating character, such as XXXXXX or 999999.', 'kb-doc-14-nist-sp-800-53-p386-11', 0, 41, '14-nist-sp-800-53', 'retrieved', '865EF6015F5E4B0924852BA7869A480D7580554E3ADD7C34B061F5B59FFEFBBA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-12', 'doc-14-nist-sp-800-53', '', 386, 'Identifiers can be encrypted or hashed so that the linked records remain linked. In the case of encryption or hashing, algorithms are employed that require the use of a key, including the Advanced Encryption Standard or a Hash-based Message Authentication Code.', 'kb-doc-14-nist-sp-800-53-p386-12', 0, 41, '14-nist-sp-800-53', 'retrieved', '3364BF5A599C20F32918D7DEC4EB558B1BB448DCAEA12A62CE3AA2F06213857D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-13', 'doc-14-nist-sp-800-53', '', 386, 'Implementations may use the same key for all identifiers or use a different key for each identifier. Using a different key for each identifier provides a higher degree of security and privacy. Identifiers can alternatively be replaced with a keyword, including transforming “George Washington” to “PATIENT” or replacing it with a surrogate value, such as transforming “George Washington” to “Abraham Polk.” Related Controls: SC-12, SC-13.', 'kb-doc-14-nist-sp-800-53-p386-13', 0, 65, '14-nist-sp-800-53', 'retrieved', 'EE5A7C0846B39ACC3E81D3A78D6CAE765E27D79456FD10D8F1EBB878DCBBBA08', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-14', 'doc-14-nist-sp-800-53', '', 386, '(5) DE-IDENTIFICATION | STATISTICAL DISCLOSURE CONTROL Manipulate numerical data, contingency tables, and statistical findings so that no individual or organization is identifiable in the results of the analysis.', 'kb-doc-14-nist-sp-800-53-p386-14', 0, 28, '14-nist-sp-800-53', 'retrieved', '9AF6CFB4740828EE9A4A0FEA762F2D79F7F0830EED4D4922E09E15800B89DB11', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p386-15', 'doc-14-nist-sp-800-53', '', 386, 'Discussion: Many types of statistical analyses can result in the disclosure of information about individuals even if only summary information is provided. For example, if a school that publishes a monthly table with the number of minority students enrolled, reports that it has 10-19 such students in January, and subsequently reports that it has 20-29 such students in March, then it can be inferred that the student who enrolled in February was a minority.', 'kb-doc-14-nist-sp-800-53-p386-15', 0, 74, '14-nist-sp-800-53', 'retrieved', '696B5EF198465FEE8A762CCDDD3FD58AE5E2A7C25B2B7783ECCAB2389BBDEBC8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-1', 'doc-14-nist-sp-800-53', '', 387, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 360 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p387-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '4508E8C3556372365DCE917AABFD60D10EE92D256B6216C6CC9FE765AED20EF8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-2', 'doc-14-nist-sp-800-53', '', 387, '(6) DE-IDENTIFICATION | DIFFERENTIAL PRIVACY Prevent disclosure of personally identifiable information by adding non-deterministic noise to the results of mathematical operations before the results are reported.', 'kb-doc-14-nist-sp-800-53-p387-2', 0, 26, '14-nist-sp-800-53', 'retrieved', 'AA25511485AD54A30A7BB0DBB3F95CEC56CEA8145F5E21C0CAB018AA43CB88FD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-3', 'doc-14-nist-sp-800-53', '', 387, 'Discussion: The mathematical definition for differential privacy holds that the result of a dataset analysis should be approximately the same before and after the addition or removal of a single data record (which is assumed to be the data from a single individual). In its most basic form, differential privacy applies only to online query systems. However, it can also be used to produce machine-learning statistical classifiers and synthetic data. Differential privacy comes at the cost of decreased accuracy of results, forcing organizations to quantify the trade-off between privacy protection and the overall accuracy, usefulness, and utility of the de-identified dataset. Non-deterministic noise can include adding small, random values to the results of mathematical operations in dataset analysis.', 'kb-doc-14-nist-sp-800-53-p387-3', 0, 118, '14-nist-sp-800-53', 'retrieved', 'DDE5E75F94E75D4D22DEB17EAA6A4270E5470C3F8D19CFB2E9992418E7F50FC2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-5', 'doc-14-nist-sp-800-53', '', 387, '(7) DE-IDENTIFICATION | VALIDATED ALGORITHMS AND SOFTWARE Perform de-identification using validated algorithms and software that is validated to implement the algorithms.', 'kb-doc-14-nist-sp-800-53-p387-5', 0, 21, '14-nist-sp-800-53', 'retrieved', 'B9AE01F02BF3E34F5085A5EEE4674EF390C93B81E6CB57F0E792D3F6B21E4F20', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-6', 'doc-14-nist-sp-800-53', '', 387, 'Discussion: Algorithms that appear to remove personally identifiable information from a dataset may in fact leave information that is personally identifiable or data that is re- identifiable. Software that is claimed to implement a validated algorithm may contain bugs or implement a different algorithm. Software may de-identify one type of data, such as integers, but not de-identify another type of data, such as floating point numbers. For these reasons, de-identification is performed using algorithms and software that are validated.', 'kb-doc-14-nist-sp-800-53-p387-6', 0, 79, '14-nist-sp-800-53', 'retrieved', 'B9E8845C7BE0B867A8DC4E386AB66549F25E4E66867977159FB4D703B463EF7C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-8', 'doc-14-nist-sp-800-53', '', 387, '(8) DE-IDENTIFICATION | MOTIVATED INTRUDER Perform a motivated intruder test on the de-identified dataset to determine if the identified data remains or if the de-identified data can be re-identified.', 'kb-doc-14-nist-sp-800-53-p387-8', 0, 29, '14-nist-sp-800-53', 'retrieved', 'E12AAE4C09B1E13AD0FD2B9A964C22524C9D46408BA0979DB5A3A6DB10D40CD9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-9', 'doc-14-nist-sp-800-53', '', 387, 'Discussion: A motivated intruder test is a test in which an individual or group takes a data release and specified resources and attempts to re-identify one or more individuals in the de-identified dataset. Such tests specify the amount of inside knowledge, computational resources, financial resources, data, and skills that intruders possess to conduct the tests. A motivated intruder test can determine if the de-identification is insufficient. It can also be a useful diagnostic tool to assess if de-identification is likely to be sufficient. However, the test alone cannot prove that de-identification is sufficient.', 'kb-doc-14-nist-sp-800-53-p387-9', 0, 93, '14-nist-sp-800-53', 'retrieved', 'BCA86A3F8B2D5D423753953C7905AD098514A138B4DA00449DB881120AD599F8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-12', 'doc-14-nist-sp-800-53', '', 387, 'SI-20 TAINTING Control: Embed data or capabilities in the following systems or system components to determine if organizational data has been exfiltrated or improperly removed from the organization: [Assignment: organization-defined systems or system components].', 'kb-doc-14-nist-sp-800-53-p387-12', 0, 34, '14-nist-sp-800-53', 'retrieved', '3110D7803EBA65D015BD7107A8FBFF8C01E0EB3FB7093612D342102944F7959D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-13', 'doc-14-nist-sp-800-53', '', 387, 'Discussion: Many cyber-attacks target organizational information, or information that the organization holds on behalf of other entities (e.g., personally identifiable information), and exfiltrate that data. In addition, insider attacks and erroneous user procedures can remove information from the system that is in violation of the organizational policies. Tainting approaches can range from passive to active. A passive tainting approach can be as simple as adding false email names and addresses to an internal database. If the organization receives email at one of the false email addresses, it knows that the database has been compromised.', 'kb-doc-14-nist-sp-800-53-p387-13', 0, 94, '14-nist-sp-800-53', 'retrieved', '10305420F3E06E4E74E7553AE0A6E2937B9A84F195ACDEB724C9829A637757B3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p387-14', 'doc-14-nist-sp-800-53', '', 387, 'Moreover, the organization knows that the email was sent by an unauthorized entity, so any', 'kb-doc-14-nist-sp-800-53-p387-14', 0, 15, '14-nist-sp-800-53', 'retrieved', '0164F2B501702174647A3484B776813DA7BED6A7B7696327316CF86EFBCD2833', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
