INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p388-3', 'doc-14-nist-sp-800-53', '', 388, 'Finally, an active tainting approach can include embedding software in the data that is able to “call home,” thereby alerting the organization to its “capture,” and possibly its location, and the path by which it was exfiltrated or removed.', 'kb-doc-14-nist-sp-800-53-p388-3', 0, 39, '14-nist-sp-800-53', 'retrieved', 'F1234BCD3C9EB7764D23E3BC489BFBDAA77DE45DF06BD4C9255FA0C7FFB3F34D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
