INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p388-7', 'doc-14-nist-sp-800-53', '', 388, 'SI-21 INFORMATION REFRESH Control: Refresh [Assignment: organization-defined information] at [Assignment: organization- defined frequencies] or generate the information on demand and delete the information when no longer needed.', 'kb-doc-14-nist-sp-800-53-p388-7', 0, 27, '14-nist-sp-800-53', 'retrieved', '0EA947B7ED4A9C9B9643888F702310E754423D621C2C14D9DE6EB979770C5F2D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
