VALUES ('doc-14-nist-sp-800-53-p388-17', 'doc-14-nist-sp-800-53', '', 388, 'SI-23 INFORMATION FRAGMENTATION Control: Based on [Assignment: organization-defined circumstances]:', 'kb-doc-14-nist-sp-800-53-p388-17', 0, 9, '14-nist-sp-800-53', 'retrieved', 'DF89E46CBD317D4ED4D39001198D47D13B918767E420B5D0064512A416D259C4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
