INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p389-3', 'doc-14-nist-sp-800-53', '', 389, 'Discussion: One objective of the advanced persistent threat is to exfiltrate valuable information.', 'kb-doc-14-nist-sp-800-53-p389-3', 0, 13, '14-nist-sp-800-53', 'retrieved', '477D8A629A2C0C23A8C682D2668DD7837F0D3F66D1B6AD84D9B2A63966BD7DE2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p389-4', 'doc-14-nist-sp-800-53', '', 389, 'Once exfiltrated, there is generally no way for the organization to recover the lost information.', 'kb-doc-14-nist-sp-800-53-p389-4', 0, 15, '14-nist-sp-800-53', 'retrieved', '028A2958EDC9A8DA2ED0C180277AA31C9EF3EB4ABFC8D659C46EA2F7A7D35432', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p389-5', 'doc-14-nist-sp-800-53', '', 389, 'Therefore, organizations may consider dividing the information into disparate elements and distributing those elements across multiple systems or system components and locations. Such actions will increase the adversary’s work factor to capture and exfiltrate the desired information and, in so doing, increase the probability of detection. The fragmentation of information impacts the organization’s ability to access the information in a timely manner. The extent of the fragmentation is dictated by the impact or classification level (and value) of the information, threat intelligence information received, and whether data tainting is used (i.e., data tainting- derived information about the exfiltration of some information could result in the fragmentation of the remaining information).', 'kb-doc-14-nist-sp-800-53-p389-5', 0, 110, '14-nist-sp-800-53', 'retrieved', '062D3F270873030C3D08E3C6DE63DAAFCAD73917E9232F068DF678247FCAAEB8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
