VALUES ('doc-14-nist-sp-800-53-p390-1', 'doc-14-nist-sp-800-53', '', 390, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 363 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p390-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'A220080A8AD5E20A74840F714A33F0B6E3347B96C35C187B9A3DEADBAB62D5DB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
