VALUES ('doc-14-nist-sp-800-53-p391-1', 'doc-14-nist-sp-800-53', '', 391, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 364 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p391-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'A3E755A15BD0A89E655FA53398C048D8CF3FFCD540253E214DFA6CE4EE1974A7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
