VALUES ('doc-14-nist-sp-800-53-p391-2', 'doc-14-nist-sp-800-53', '', 391, 'References: [FASC18], [41 CFR 201], [EO 13873], [CNSSD 505], [SP 800-12], [SP 800-30], [SP 800- 39], [SP 800-100], [SP 800-161].', 'kb-doc-14-nist-sp-800-53-p391-2', 0, 20, '14-nist-sp-800-53', 'retrieved', 'F971C42DE46FE184ED81A627227FE10AC69677E9908C2AB4E5E55F840F58E5BD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
