VALUES ('doc-14-nist-sp-800-53-p392-1', 'doc-14-nist-sp-800-53', '', 392, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 365 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p392-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '786FAA49FF7489A3060A5A58CB13A9CE902BC044060264AA1D5E2A150B7675D8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
