VALUES ('doc-14-nist-sp-800-53-p393-1', 'doc-14-nist-sp-800-53', '', 393, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 366 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p393-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '29D8716E47B9CF60459D9D8325FAE4C267F8A63F6C8E2085F0410F6C2B2BEB53', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
