VALUES ('doc-14-nist-sp-800-53-p393-11', 'doc-14-nist-sp-800-53', '', 393, 'References: [FASC18], [41 CFR 201], [EO 13873], [ISO 20243], [SP 800-30], [SP 800-161], [IR 7622].', 'kb-doc-14-nist-sp-800-53-p393-11', 0, 15, '14-nist-sp-800-53', 'retrieved', 'B5EB74BFF94C828F9C89B2875EC72A5B61B2B22826859A940F3C6E933DE0622F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
