VALUES ('doc-14-nist-sp-800-53-p394-1', 'doc-14-nist-sp-800-53', '', 394, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 367 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p394-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '6DFCB6018E11A3F756F9DC2C82A7B1EE477E08AB10F8B3AA18DF44292666919F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
