VALUES ('doc-14-nist-sp-800-53-p396-1', 'doc-14-nist-sp-800-53', '', 396, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 369 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p396-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '6CF8D5FCBAA81305F95A7377E74544BFCE2E6BE581CA29F7B7DE6F8112BB1211', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
