INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p396-5', 'doc-14-nist-sp-800-53', '', 396, 'Control Enhancements: (1) ACQUISITION STRATEGIES, TOOLS, AND METHODS | ADEQUATE SUPPLY Employ the following controls to ensure an adequate supply of [Assignment: organization- defined critical system components]: [Assignment: organization-defined controls].', 'kb-doc-14-nist-sp-800-53-p396-5', 0, 30, '14-nist-sp-800-53', 'retrieved', '40A18F908D681E5F9E30466E6365F4CCBA0C7A202198BA949347E0A7AB08CE13', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
