VALUES ('doc-14-nist-sp-800-53-p396-12', 'doc-14-nist-sp-800-53', '', 396, 'SR-6 SUPPLIER ASSESSMENTS AND REVIEWS Control: Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p396-12', 0, 31, '14-nist-sp-800-53', 'retrieved', 'CCF60B4DB3F50D50FCDE8C6A210108D311F36C03412E6E60D8EE6F83C12D70A2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
