VALUES ('doc-14-nist-sp-800-53-p397-1', 'doc-14-nist-sp-800-53', '', 397, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 370 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p397-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'CF2417395A1015161CAA7BF6627FC485268AA09118D24146B29F8A6B815D9F64', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
