VALUES ('doc-14-nist-sp-800-53-p397-9', 'doc-14-nist-sp-800-53', '', 397, 'SR-7 SUPPLY CHAIN OPERATIONS SECURITY Control: Employ the following Operations Security (OPSEC) controls to protect supply chain- related information for the system, system component, or system service: [Assignment: organization-defined Operations Security (OPSEC) controls].', 'kb-doc-14-nist-sp-800-53-p397-9', 0, 33, '14-nist-sp-800-53', 'retrieved', '622DB183CE0A4EF1E3D6BBA1DCE47B0856C3712B45341FDE7162BC44534D0979', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
