VALUES ('doc-14-nist-sp-800-53-p398-2', 'doc-14-nist-sp-800-53', '', 398, 'organizations to withhold mission or business information from suppliers and may include the use of intermediaries to hide the end use or users of systems, system components, or system services.', 'kb-doc-14-nist-sp-800-53-p398-2', 0, 30, '14-nist-sp-800-53', 'retrieved', 'BFFCDBEA86904AC7C7C12E594F59022A66DFC9FF66E1918C57F333C2F06EFD5C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
