INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p398-6', 'doc-14-nist-sp-800-53', '', 398, 'SR-8 NOTIFICATION AGREEMENTS Control: Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the [Selection (one or more): notification of supply chain compromises; results of assessments or audits; [Assignment: organization-defined information]].', 'kb-doc-14-nist-sp-800-53-p398-6', 0, 42, '14-nist-sp-800-53', 'retrieved', 'C97124988708C33518D5AD87B22E20CF9F5031797196D1E12C2085AFB8D9009E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
