VALUES ('doc-14-nist-sp-800-53-p398-11', 'doc-14-nist-sp-800-53', '', 398, 'SR-9 TAMPER RESISTANCE AND DETECTION Control: Implement a tamper protection program for the system, system component, or system service.', 'kb-doc-14-nist-sp-800-53-p398-11', 0, 19, '14-nist-sp-800-53', 'retrieved', '9C14F12C556D9766E9BF5D5CB55240094EB9DF3D459F439796E4A136D121FBF9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
