INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p398-12', 'doc-14-nist-sp-800-53', '', 398, 'Discussion: Anti-tamper technologies, tools, and techniques provide a level of protection for systems, system components, and services against many threats, including reverse engineering, modification, and substitution. Strong identification combined with tamper resistance and/or tamper detection is essential to protecting systems and components during distribution and when in use.', 'kb-doc-14-nist-sp-800-53-p398-12', 0, 48, '14-nist-sp-800-53', 'retrieved', '14CADFFB118502E623F62048A0D21ABED7FA654301135EF172159F0FB2021306', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
