VALUES ('doc-14-nist-sp-800-53-p398-13', 'doc-14-nist-sp-800-53', '', 398, 'Related Controls: PE-3, PM-30, SA-15, SI-4, SI-7, SR-3, SR-4, SR-5, SR-10, SR-11.', 'kb-doc-14-nist-sp-800-53-p398-13', 0, 12, '14-nist-sp-800-53', 'retrieved', '1DBF6E6B422506E50436A0961ADA56EF274B0DCA58395599D68F6C4BF67B57BB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
