VALUES ('doc-14-nist-sp-800-53-p398-14', 'doc-14-nist-sp-800-53', '', 398, 'Control Enhancements: (1) TAMPER RESISTANCE AND DETECTION | MULTIPLE STAGES OF SYSTEM DEVELOPMENT LIFE CYCLE Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle.', 'kb-doc-14-nist-sp-800-53-p398-14', 0, 27, '14-nist-sp-800-53', 'retrieved', '80B75D7D3549C2DBFDF539B5020A18E2F9F9D4CC2EBD4499115AA49AB1C92C95', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
