INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p398-15', 'doc-14-nist-sp-800-53', '', 398, 'Discussion: The system development life cycle includes research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal.', 'kb-doc-14-nist-sp-800-53-p398-15', 0, 20, '14-nist-sp-800-53', 'retrieved', 'D53D9C32A60F5E7F6F77233F91ABFD84085C511FF4545EF78245CC5E3E096E84', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
