INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p398-16', 'doc-14-nist-sp-800-53', '', 398, 'Organizations use a combination of hardware and software techniques for tamper resistance and detection. Organizations use obfuscation and self-checking to make reverse engineering and modifications more difficult, time-consuming, and expensive for adversaries. The customization of systems and system components can make substitutions easier to detect and therefore limit damage.', 'kb-doc-14-nist-sp-800-53-p398-16', 0, 49, '14-nist-sp-800-53', 'retrieved', 'C335CDB7460620F470B0098CD616D271CE016ACA9E40F84C23A35B4054F20892', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
