INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-3', 'doc-14-nist-sp-800-53', '', 399, 'SR-10 INSPECTION OF SYSTEMS OR COMPONENTS Control: Inspect the following systems or system components [Selection (one or more): at random; at [Assignment: organization-defined frequency], upon [Assignment: organization- defined indications of need for inspection]] to detect tampering: [Assignment: organization- defined systems or system components].', 'kb-doc-14-nist-sp-800-53-p399-3', 0, 43, '14-nist-sp-800-53', 'retrieved', '94E07F0DD49E32EBEF9D8781FBA046D835F5A1430C829990A57B62D39A0FA9ED', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
