INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-4', 'doc-14-nist-sp-800-53', '', 399, 'Discussion: The inspection of systems or systems components for tamper resistance and detection addresses physical and logical tampering and is applied to systems and system components removed from organization-controlled areas. Indications of a need for inspection include changes in packaging, specifications, factory location, or entity in which the part is purchased, and when individuals return from travel to high-risk locations.', 'kb-doc-14-nist-sp-800-53-p399-4', 0, 60, '14-nist-sp-800-53', 'retrieved', 'F0EA512BEA9C1BC5D9DF5438842E78DE07B9A0086F96004B9E422C6074024C07', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-7', 'doc-14-nist-sp-800-53', '', 399, 'SR-11 COMPONENT AUTHENTICITY Control: a. Develop and implement anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the system; and b. Report counterfeit system components to [Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]].', 'kb-doc-14-nist-sp-800-53-p399-7', 0, 51, '14-nist-sp-800-53', 'retrieved', '3DF8B5F0B29BAF31384B98B1D81D38FB1A0C60F60D6DC402B33E4167583E8D3E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-8', 'doc-14-nist-sp-800-53', '', 399, 'Discussion: Sources of counterfeit components include manufacturers, developers, vendors, and contractors. Anti-counterfeiting policies and procedures support tamper resistance and provide a level of protection against the introduction of malicious code. External reporting organizations include CISA.', 'kb-doc-14-nist-sp-800-53-p399-8', 0, 35, '14-nist-sp-800-53', 'retrieved', '627A8F3328F8C532F50A7861D1AC34D8703E3A8A4D867F32003EB4A64CD73907', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-10', 'doc-14-nist-sp-800-53', '', 399, 'Control Enhancements: (1) COMPONENT AUTHENTICITY | ANTI-COUNTERFEIT TRAINING Train [Assignment: organization-defined personnel or roles] to detect counterfeit system components (including hardware, software, and firmware).', 'kb-doc-14-nist-sp-800-53-p399-10', 0, 24, '14-nist-sp-800-53', 'retrieved', 'A6DF76960F8083D4323CCB97EBBBF86D6273BF2033D2764E8100157FF6C54067', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
