INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-13', 'doc-14-nist-sp-800-53', '', 399, '(2) COMPONENT AUTHENTICITY | CONFIGURATION CONTROL FOR COMPONENT SERVICE AND REPAIR Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: [Assignment: organization-defined system components].', 'kb-doc-14-nist-sp-800-53-p399-13', 0, 36, '14-nist-sp-800-53', 'retrieved', 'D8163FEF59DB67C4D4D2CB51BF3A9703AB488C1CA688294D66C11FC551690FE4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
