VALUES ('doc-14-nist-sp-800-53-p399-16', 'doc-14-nist-sp-800-53', '', 399, '(3) COMPONENT AUTHENTICITY | ANTI-COUNTERFEIT SCANNING Scan for counterfeit system components [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p399-16', 0, 14, '14-nist-sp-800-53', 'retrieved', 'DB3D96577ED7BE5C7291D7A6F048B8A6A9BF9AC5F6174DE803C2CCF04E32035B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
