INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p399-17', 'doc-14-nist-sp-800-53', '', 399, 'Discussion: The type of component determines the type of scanning to be conducted (e.g., web application scanning if the component is a web application).', 'kb-doc-14-nist-sp-800-53-p399-17', 0, 24, '14-nist-sp-800-53', 'retrieved', '3E0E711DDF70B0C71ABEA6C7D544C67935B595695CB2A4E4AB6BD07CBEB33490', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
