VALUES ('doc-14-nist-sp-800-53-p400-3', 'doc-14-nist-sp-800-53', '', 400, 'SR-12 COMPONENT DISPOSAL Control: Dispose of [Assignment: organization-defined data, documentation, tools, or system components] using the following techniques and methods: [Assignment: organization-defined techniques and methods].', 'kb-doc-14-nist-sp-800-53-p400-3', 0, 25, '14-nist-sp-800-53', 'retrieved', 'E733E3997B0A2D686574BBEF8CE4A6F11DD21145EE9828890E47B3E9C7A76C5C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
