INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p421-2', 'doc-14-nist-sp-800-53', '', 421, 'APPENDIX A GLOSSARY COMMON TERMS AND DEFINITIONS Appendix A provides definitions for terminology used in NIST Special Publication 800-53. Sources for terms used in this publication are cited as applicable. Where no citation is noted, the source of the definition is Special Publication 800-53.', 'kb-doc-14-nist-sp-800-53-p421-2', 0, 44, '14-nist-sp-800-53', 'retrieved', '63A1D018A407CD99600B68BAF6FC145A7700DD40C1F5CB7FBD1CC33BDF27FD7B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
