VALUES ('doc-14-nist-sp-800-53-p423-2', 'doc-14-nist-sp-800-53', '', 423, 'authenticator Something that the claimant possesses and controls (typically a cryptographic module or password) that is used to authenticate the claimant’s identity. This was previously referred to as a token.', 'kb-doc-14-nist-sp-800-53-p423-2', 0, 30, '14-nist-sp-800-53', 'retrieved', '02562183370BA7603BE9A32C339439749ED78C2673102693CCFFF7C74EABFA9E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
