VALUES ('doc-14-nist-sp-800-53-p423-3', 'doc-14-nist-sp-800-53', '', 423, 'authenticity The property of being genuine and being able to be verified and trusted; confidence in the validity of a transmission, message, or message originator. See authentication.', 'kb-doc-14-nist-sp-800-53-p423-3', 0, 27, '14-nist-sp-800-53', 'retrieved', 'C9ADFFF38C9B1A68FA147306B225D93381F146EB9B4B7290BC7FFAD138578D85', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
