VALUES ('doc-14-nist-sp-800-53-p423-5', 'doc-14-nist-sp-800-53', '', 423, 'authorization boundary [OMB A-130] All components of an information system to be authorized for operation by an authorizing official. This excludes separately authorized systems to which the information system is connected.', 'kb-doc-14-nist-sp-800-53-p423-5', 0, 31, '14-nist-sp-800-53', 'retrieved', '5785EA57EBB4A1398EF94805BDFC219F276EC5DAA82442D047C64586A3FF8EE2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
