INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p423-6', 'doc-14-nist-sp-800-53', '', 423, 'authorization to operate [OMB A-130] The official management decision given by a senior Federal official or officials to authorize operation of an information system and to explicitly accept the risk to agency operations (including mission, functions, image, or reputation), agency assets, individuals, other organizations, and the Nation based on the implementation of an agreed-upon set of security and privacy controls. Authorization also applies to common controls inherited by agency information systems.', 'kb-doc-14-nist-sp-800-53-p423-6', 0, 71, '14-nist-sp-800-53', 'retrieved', 'ED1A22F3F3C7E8990165866082BC15E6E6930A7811915BADE324F5718F2153D9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p423-7', 'doc-14-nist-sp-800-53', '', 423, 'authorizing official [OMB A-130] A senior Federal official or executive with the authority to authorize (i.e., assume responsibility for) the operation of an information system or the use of a designated set of common controls at an acceptable level of risk to agency operations (including mission, functions, image, or reputation), agency assets, individuals, other organizations, and the Nation.', 'kb-doc-14-nist-sp-800-53-p423-7', 0, 58, '14-nist-sp-800-53', 'retrieved', 'E4E695CEB803715FB3ECD42A2359A4B7C806545402C4AE903FF59B40EDADD56A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
