VALUES ('doc-14-nist-sp-800-53-p424-2', 'doc-14-nist-sp-800-53', '', 424, 'boundary protection device A device (e.g., gateway, router, firewall, guard, or encrypted tunnel) that facilitates the adjudication of different system security policies for connected systems or provides boundary protection. The boundary may be the authorization boundary for a system, the organizational network boundary, or a logical boundary defined by the organization.', 'kb-doc-14-nist-sp-800-53-p424-2', 0, 51, '14-nist-sp-800-53', 'retrieved', '854DBFDDF8D5345A45C260F37D789B3D79D95EE0E9AC00FA88197663C45BB026', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
