INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p424-3', 'doc-14-nist-sp-800-53', '', 424, 'breach [OMB M-17-12] The loss of control, compromise, unauthorized disclosure, unauthorized acquisition, or any similar occurrence where: a person other than an authorized user accesses or potentially accesses personally identifiable information; or an authorized user accesses personally identifiable information for another than authorized purpose.', 'kb-doc-14-nist-sp-800-53-p424-3', 0, 44, '14-nist-sp-800-53', 'retrieved', '843A86035C2255967171FF5B2273899F9EDAA27F5F26EF91D1ECBDC4AAB71595', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
