VALUES ('doc-14-nist-sp-800-53-p424-5', 'doc-14-nist-sp-800-53', '', 424, 'capability A combination of mutually reinforcing security and/or privacy controls implemented by technical, physical, and procedural means. Such controls are typically selected to achieve a common information security- or privacy-related purpose.', 'kb-doc-14-nist-sp-800-53-p424-5', 0, 31, '14-nist-sp-800-53', 'retrieved', '10ED31B96334E06138B8824E0B31FAD6700536B4A26FE804099D44314B9B71E7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
