VALUES ('doc-14-nist-sp-800-53-p424-7', 'doc-14-nist-sp-800-53', '', 424, 'Central management includes planning, implementing, assessing, authorizing, and monitoring the organization-defined, centrally managed security and privacy controls and processes.', 'kb-doc-14-nist-sp-800-53-p424-7', 0, 19, '14-nist-sp-800-53', 'retrieved', 'D4717B4A8139472F1EE1C3995E967FF94C760E0CD34CBA7D30F4F63369F79D29', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
