INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p424-10', 'doc-14-nist-sp-800-53', '', 424, 'chief information officer [OMB A-130] The senior official that provides advice and other assistance to the head of the agency and other senior management personnel of the agency to ensure that IT is acquired and information resources are managed for the agency in a manner that achieves the agency’s strategic goals and information resources management goals; and is responsible for ensuring agency compliance with, and prompt, efficient, and effective implementation of, the information policies and information resources management responsibilities, including the reduction of information collection burdens on the public.', 'kb-doc-14-nist-sp-800-53-p424-10', 0, 89, '14-nist-sp-800-53', 'retrieved', 'DFDA61C303A089B293CDCDC8FFA08BB5F3F678B1EAD0864266D49E15DB4690D9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
