VALUES ('doc-14-nist-sp-800-53-p424-13', 'doc-14-nist-sp-800-53', '', 424, 'classified national security information [EO 13526] Information that has been determined pursuant to Executive Order (E.O.) 13526 or any predecessor order to require protection against unauthorized disclosure and is marked to indicate its classified status when in documentary form.', 'kb-doc-14-nist-sp-800-53-p424-13', 0, 39, '14-nist-sp-800-53', 'retrieved', 'D14E80CCA13EF9F78FD7DB0307C48CFA5E38D2823BB04A15F94422F1FC1BB487', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
