VALUES ('doc-14-nist-sp-800-53-p425-2', 'doc-14-nist-sp-800-53', '', 425, 'commodity service A system service provided by a commercial service provider to a large and diverse set of consumers. The organization acquiring or receiving the commodity service possesses limited visibility into the management structure and operations of the provider, and while the organization may be able to negotiate service-level agreements, the organization is typically not able to require that the provider implement specific security or privacy controls.', 'kb-doc-14-nist-sp-800-53-p425-2', 0, 67, '14-nist-sp-800-53', 'retrieved', '0D8278C780F6B4A5829DD05064B633B2EE55FF030DE2B3BD57FF0420D2A35D67', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
