VALUES ('doc-14-nist-sp-800-53-p425-4', 'doc-14-nist-sp-800-53', '', 425, 'common control [OMB A-130] A security or privacy control that is inherited by multiple information systems or programs.', 'kb-doc-14-nist-sp-800-53-p425-4', 0, 18, '14-nist-sp-800-53', 'retrieved', '13C74DDDD63E0F651681C569753DC70E9E8AD164078A28540031353ECEB98915', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
