VALUES ('doc-14-nist-sp-800-53-p425-13', 'doc-14-nist-sp-800-53', '', 425, 'configuration management [SP 800-128] A collection of activities focused on establishing and maintaining the integrity of information technology products and systems, through control of processes for initializing, changing, and monitoring the configurations of those products and systems throughout the system development life cycle.', 'kb-doc-14-nist-sp-800-53-p425-13', 0, 43, '14-nist-sp-800-53', 'retrieved', '60F8023F1AB8CE8BBED38B7CCF1D9E4EEB77E73BFA6B222E3A90E4BE179DA8BC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
