INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p426-5', 'doc-14-nist-sp-800-53', '', 426, 'control assessment [SP 800-37] The testing or evaluation of the controls in an information system or an organization to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting the security or privacy requirements for the system or the organization.', 'kb-doc-14-nist-sp-800-53-p426-5', 0, 52, '14-nist-sp-800-53', 'retrieved', 'F5D159FB65DE8EED381D6F7EEC5CDD9876A90C5DCA71E0C7D045F14112B1410D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
