VALUES ('doc-14-nist-sp-800-53-p426-7', 'doc-14-nist-sp-800-53', '', 426, 'control baseline [SP 800-53B] Predefined sets of controls specifically assembled to address the protection needs of groups, organizations, or communities of interest. See privacy control baseline or security control baseline.', 'kb-doc-14-nist-sp-800-53-p426-7', 0, 30, '14-nist-sp-800-53', 'retrieved', '972764D81F1F99584A9B6D2C9913E886518B4694C65E34ACEF6F7417F80B24C5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
