VALUES ('doc-14-nist-sp-800-53-p426-8', 'doc-14-nist-sp-800-53', '', 426, 'control effectiveness A measure of whether a security or privacy control contributes to the reduction of information security or privacy risk.', 'kb-doc-14-nist-sp-800-53-p426-8', 0, 21, '14-nist-sp-800-53', 'retrieved', '904A0A6F15164137825EC6C94842B9CE9707AB01C9F68B32790976A1841A0343', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
