VALUES ('doc-14-nist-sp-800-53-p426-9', 'doc-14-nist-sp-800-53', '', 426, 'control enhancement Augmentation of a security or privacy control to build in additional but related functionality to the control, increase the strength of the control, or add assurance to the control.', 'kb-doc-14-nist-sp-800-53-p426-9', 0, 31, '14-nist-sp-800-53', 'retrieved', 'B2544222A7C4E7119F0B9B854DEA37A951139BB827EBC75B20A07D14D2B6DF07', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
