INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p426-10', 'doc-14-nist-sp-800-53', '', 426, 'control inheritance A situation in which a system or application receives protection from security or privacy controls (or portions of controls) that are developed, implemented, assessed, authorized, and monitored by entities other than those responsible for the system or application; entities either internal or external to the organization where the system or application resides. See common control.', 'kb-doc-14-nist-sp-800-53-p426-10', 0, 57, '14-nist-sp-800-53', 'retrieved', '1A55B5988DAF84A4C5CECB04753947E858B584FA186C13FBB2E5038BB29AF7B7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
