VALUES ('doc-14-nist-sp-800-53-p426-12', 'doc-14-nist-sp-800-53', '', 426, 'controlled area Any area or space for which an organization has confidence that the physical and procedural protections provided are sufficient to meet the requirements established for protecting the information and/or information system.', 'kb-doc-14-nist-sp-800-53-p426-12', 0, 33, '14-nist-sp-800-53', 'retrieved', '03CFE266DA287E037CF29B5867206FAE06742006089954ED24AA74F842ED5A3E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
