VALUES ('doc-14-nist-sp-800-53-p426-14', 'doc-14-nist-sp-800-53', '', 426, 'An interface to a system with a set of mechanisms that enforces the security policies and controls the flow of information between connected systems.', 'kb-doc-14-nist-sp-800-53-p426-14', 0, 24, '14-nist-sp-800-53', 'retrieved', '3C18CC50D7F0969454FBEB6E032140FD0F777E539DE401D32A08117A93A3FD80', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
