VALUES ('doc-14-nist-sp-800-53-p427-4', 'doc-14-nist-sp-800-53', '', 427, 'counterfeit [SP 800-161] An unauthorized copy or substitute that has been identified, marked, and/or altered by a source other than the item''s legally authorized source and has been misrepresented to be an authorized item of the legally authorized source.', 'kb-doc-14-nist-sp-800-53-p427-4', 0, 39, '14-nist-sp-800-53', 'retrieved', '6E118E813E07296599CE118E315E5FDB2E97D97207AD2694F29A176BF1ADCB6D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
