VALUES ('doc-14-nist-sp-800-53-p427-5', 'doc-14-nist-sp-800-53', '', 427, 'countermeasures [FIPS 200] Actions, devices, procedures, techniques, or other measures that reduce the vulnerability of a system. Synonymous with security controls and safeguards.', 'kb-doc-14-nist-sp-800-53-p427-5', 0, 23, '14-nist-sp-800-53', 'retrieved', '9314B8ECB4F29D87B365B5AFCC11A38CE8FE2E7844536E76CC5715176FE2230D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
