VALUES ('doc-14-nist-sp-800-53-p427-6', 'doc-14-nist-sp-800-53', '', 427, 'covert channel [CNSSI 4009] An unintended or unauthorized intra-system channel that enables two cooperating entities to transfer information in a way that violates the system''s security policy but does not exceed the entities'' access authorizations.', 'kb-doc-14-nist-sp-800-53-p427-6', 0, 35, '14-nist-sp-800-53', 'retrieved', 'A463F61A5C61A3165350A970543E1AE11A7FA9FEB987500FBF47CACAFAD81D81', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
