INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p428-8', 'doc-14-nist-sp-800-53', '', 428, 'defense in breadth [CNSSI 4009] A planned, systematic set of multidisciplinary activities that seek to identify, manage, and reduce risk of exploitable vulnerabilities at every stage of the system, network, or subcomponent life cycle, including system, network, or product design and development; manufacturing; packaging; assembly; system integration; distribution; operations; maintenance; and retirement.', 'kb-doc-14-nist-sp-800-53-p428-8', 0, 52, '14-nist-sp-800-53', 'retrieved', 'C161E55BFE0E339D58FCE7375BB8EA3E639C50C878E8DA44E594F3257C3A30C2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
