VALUES ('doc-14-nist-sp-800-53-p428-9', 'doc-14-nist-sp-800-53', '', 428, 'defense in depth An information security strategy that integrates people, technology, and operations capabilities to establish variable barriers across multiple layers and missions of the organization.', 'kb-doc-14-nist-sp-800-53-p428-9', 0, 26, '14-nist-sp-800-53', 'retrieved', '843D973E660D9B14431FAD4800CE306367331F248EBD0449E2F8BF739731EADB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
