VALUES ('doc-14-nist-sp-800-53-p428-10', 'doc-14-nist-sp-800-53', '', 428, 'depth [SP 800-53A] An attribute associated with an assessment method that addresses the rigor and level of detail associated with the application of the method.', 'kb-doc-14-nist-sp-800-53-p428-10', 0, 25, '14-nist-sp-800-53', 'retrieved', 'DD46F4578F560E7EEF56B7FC442F661EC426496D1830E4ABAB1D6D6DD3CA5BB9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
