INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p428-11', 'doc-14-nist-sp-800-53', '', 428, 'developer A general term that includes developers or manufacturers of systems, system components, or system services; systems integrators; vendors; and product resellers. The development of systems, components, or services can occur internally within organizations or through external entities.', 'kb-doc-14-nist-sp-800-53-p428-11', 0, 38, '14-nist-sp-800-53', 'retrieved', 'FBAEDE09DF72E9F45A7A9716263FD204FE36D31358A78EABED070BD483573470', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
