VALUES ('doc-14-nist-sp-800-53-p428-12', 'doc-14-nist-sp-800-53', '', 428, 'digital media A form of electronic media where data is stored in digital (as opposed to analog) form.', 'kb-doc-14-nist-sp-800-53-p428-12', 0, 18, '14-nist-sp-800-53', 'retrieved', '2978543680EB62071A6C8CBAC92EF6890C4A4098B4CFEADCA9390D973B973016', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
