INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p429-2', 'doc-14-nist-sp-800-53', '', 429, 'discretionary access control An access control policy that is enforced over all subjects and objects in a system where the policy specifies that a subject that has been granted access to information can do one or more of the following: pass the information to other subjects or objects; grant its privileges to other subjects; change the security attributes of subjects, objects, systems, or system components; choose the security attributes to be associated with newly- created or revised objects; or change the rules governing access control. Mandatory access controls restrict this capability.', 'kb-doc-14-nist-sp-800-53-p429-2', 0, 91, '14-nist-sp-800-53', 'retrieved', '9AD5507663E6540BA1B8B13D042D99EBB334BC8919A93D2EA64BE5BA2BB69C71', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
