VALUES ('doc-14-nist-sp-800-53-p429-3', 'doc-14-nist-sp-800-53', '', 429, 'disassociability [IR 8062] Enabling the processing of personally identifiable information or events without association to individuals or devices beyond the operational requirements of the system.', 'kb-doc-14-nist-sp-800-53-p429-3', 0, 25, '14-nist-sp-800-53', 'retrieved', 'A9187F29ABD48446314249C72CAD4BCA7FD53C63B05246865DE6E7DEEE2C2E21', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
