INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p429-5', 'doc-14-nist-sp-800-53', '', 429, 'An environment or context that includes a set of system resources and a set of system entities that have the right to access the resources as defined by a common security policy, security model, or security architecture. See security domain.', 'kb-doc-14-nist-sp-800-53-p429-5', 0, 40, '14-nist-sp-800-53', 'retrieved', '74582C552A15283638E4AEEADEE19E853BD86B48A7864894C9157B34B5CDD7EA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
