INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p429-6', 'doc-14-nist-sp-800-53', '', 429, 'enterprise [CNSSI 4009] An organization with a defined mission/goal and a defined boundary, using systems to execute that mission, and with responsibility for managing its own risks and performance. An enterprise may consist of all or some of the following business aspects: acquisition, program management, human resources, financial management, security, and systems, information and mission management. See organization.', 'kb-doc-14-nist-sp-800-53-p429-6', 0, 58, '14-nist-sp-800-53', 'retrieved', '01051186127CB5BF5A41F7C9ECB0B62FB564B51A51EAFB68C7C18CE9944B7ED9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p429-7', 'doc-14-nist-sp-800-53', '', 429, 'enterprise architecture [OMB A-130] A strategic information asset base, which defines the mission; the information necessary to perform the mission; the technologies necessary to perform the mission; and the transitional processes for implementing new technologies in response to changing mission needs; and includes a baseline architecture; a target architecture; and a sequencing plan.', 'kb-doc-14-nist-sp-800-53-p429-7', 0, 53, '14-nist-sp-800-53', 'retrieved', 'CD4BAE721939F696D145B863DCDEBEBCF9DD6F626D62983252306DD1A4A254B0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
