VALUES ('doc-14-nist-sp-800-53-p429-8', 'doc-14-nist-sp-800-53', '', 429, 'environment of operation [OMB A-130] The physical surroundings in which an information system processes, stores, and transmits information.', 'kb-doc-14-nist-sp-800-53-p429-8', 0, 18, '14-nist-sp-800-53', 'retrieved', '3F837912E8E9F1DE47BB2C584BB54133B2EC954CD87DED0B07B3AF9931F5AA3D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
