INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p429-10', 'doc-14-nist-sp-800-53', '', 429, 'executive agency [OMB A-130] An executive department specified in 5 U.S.C., Sec. 101; a military department specified in 5 U.S.C., Sec. 102; an independent establishment as defined in 5 U.S.C., Sec. 104(1); and a wholly owned Government corporation fully subject to the provisions of 31 U.S.C., Chapter 91.', 'kb-doc-14-nist-sp-800-53-p429-10', 0, 48, '14-nist-sp-800-53', 'retrieved', 'F62C2D0ED475309DC62A9183C5F86C75C5F39095CD1805161D0FB272A5A72A5B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
