VALUES ('doc-14-nist-sp-800-53-p429-12', 'doc-14-nist-sp-800-53', '', 429, 'external system (or component) A system or component of a system that is used by but is not a part of an organizational system and for which the organization has no direct control over the implementation of required security and privacy controls or the assessment of control effectiveness.', 'kb-doc-14-nist-sp-800-53-p429-12', 0, 48, '14-nist-sp-800-53', 'retrieved', '4ADE906A152E07F4E5C2B283EFB2819B7B4F7CFA4EA85215E265C192B33BBFD1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
