VALUES ('doc-14-nist-sp-800-53-p430-2', 'doc-14-nist-sp-800-53', '', 430, 'external system service A system service that is provided by an external service provider and for which the organization has no direct control over the implementation of required security and privacy controls or the assessment of control effectiveness.', 'kb-doc-14-nist-sp-800-53-p430-2', 0, 38, '14-nist-sp-800-53', 'retrieved', '6B2E989EC87E9F30120AFCF42161B169767E6A10EC77B0F494A72BC749320182', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
