VALUES ('doc-14-nist-sp-800-53-p430-3', 'doc-14-nist-sp-800-53', '', 430, 'external system service provider A provider of external system services to an organization through a variety of consumer-producer relationships, including joint ventures, business partnerships, outsourcing arrangements (i.e., through contracts, interagency agreements, lines of business arrangements), licensing agreements, and/or supply chain exchanges.', 'kb-doc-14-nist-sp-800-53-p430-3', 0, 41, '14-nist-sp-800-53', 'retrieved', 'D2F12604D244366FB70CB4E60825368E1750C82652F5023288762A8E307BD38D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
