VALUES ('doc-14-nist-sp-800-53-p430-5', 'doc-14-nist-sp-800-53', '', 430, 'failover The capability to switch over automatically (typically without human intervention or warning) to a redundant or standby system upon the failure or abnormal termination of the previously active system.', 'kb-doc-14-nist-sp-800-53-p430-5', 0, 30, '14-nist-sp-800-53', 'retrieved', 'E8FD326A86BA894F3E6EF017B92CBC3065550CDAE027C79D2B7BF3E4352FA440', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
