VALUES ('doc-14-nist-sp-800-53-p430-6', 'doc-14-nist-sp-800-53', '', 430, 'federal information system [OMB A-130] An information system used or operated by an executive agency, by a contractor of an executive agency, or by another organization on behalf of an executive agency.', 'kb-doc-14-nist-sp-800-53-p430-6', 0, 32, '14-nist-sp-800-53', 'retrieved', '351011872D1F48B58EB2C4CA07F250E9B0B20B05C09E6BC551981C8BFF7D5EA5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
