INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p430-8', 'doc-14-nist-sp-800-53', '', 430, 'firmware [CNSSI 4009] Computer programs and data stored in hardware - typically in read-only memory (ROM) or programmable read-only memory (PROM) - such that the programs and data cannot be dynamically written or modified during execution of the programs. See hardware and software.', 'kb-doc-14-nist-sp-800-53-p430-8', 0, 43, '14-nist-sp-800-53', 'retrieved', '69B16573E3FDDF350ECDBF514515A03F50D2C5368A63A32ABFB77D7F69A97A3C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
