VALUES ('doc-14-nist-sp-800-53-p430-9', 'doc-14-nist-sp-800-53', '', 430, 'hardware [CNSSI 4009] The material physical components of a system. See software and firmware.', 'kb-doc-14-nist-sp-800-53-p430-9', 0, 14, '14-nist-sp-800-53', 'retrieved', 'F00FAD4F87029B9D8BA25FA5278C443BD4CB5F64CD2236F8649D72ED900D81E3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
