VALUES ('doc-14-nist-sp-800-53-p430-10', 'doc-14-nist-sp-800-53', '', 430, 'high-impact system [FIPS 200] A system in which at least one security objective (i.e., confidentiality, integrity, or availability) is assigned a FIPS Publication 199 potential impact value of high.', 'kb-doc-14-nist-sp-800-53-p430-10', 0, 29, '14-nist-sp-800-53', 'retrieved', '56D6907D34D9B960EDE82A0C1EAE3F375DC1C11BA7F38F3DA7C5EA61E6916832', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
