VALUES ('doc-14-nist-sp-800-53-p430-11', 'doc-14-nist-sp-800-53', '', 430, 'hybrid control [OMB A-130] A security or privacy control that is implemented for an information system in part as a common control and in part as a system-specific control.', 'kb-doc-14-nist-sp-800-53-p430-11', 0, 29, '14-nist-sp-800-53', 'retrieved', 'AA226A79481CABD89E4DE3F85A7B7069A15F6B6FB4ABE2BD28B1CD2CA81690F9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
