VALUES ('doc-14-nist-sp-800-53-p430-12', 'doc-14-nist-sp-800-53', '', 430, 'identifier [FIPS 201-2] Unique data used to represent a person’s identity and associated attributes. A name or a card number are examples of identifiers.', 'kb-doc-14-nist-sp-800-53-p430-12', 0, 24, '14-nist-sp-800-53', 'retrieved', '4E255E474F4322AD3574270B4C4FAE428C9C422BEF0C237A12FC3D2F997A8D6D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
