VALUES ('doc-14-nist-sp-800-53-p430-13', 'doc-14-nist-sp-800-53', '', 430, 'A unique label used by a system to indicate a specific entity, object, or group.', 'kb-doc-14-nist-sp-800-53-p430-13', 0, 15, '14-nist-sp-800-53', 'retrieved', '0BABCEB26E389829C412886A41B4FE670E13C7F521014F5B4C2641F75CC968D5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
