INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p431-2', 'doc-14-nist-sp-800-53', '', 431, 'impact The effect on organizational operations, organizational assets, individuals, other organizations, or the Nation (including the national security interests of the United States) of a loss of confidentiality, integrity, or availability of information or a system.', 'kb-doc-14-nist-sp-800-53-p431-2', 0, 36, '14-nist-sp-800-53', 'retrieved', '57BEBBF695386A33B5FF52CED073ACBA6E3C282EE51C3279ED1896CAD64E1469', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
