INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p431-3', 'doc-14-nist-sp-800-53', '', 431, 'impact value [FIPS 199] The assessed worst-case potential impact that could result from a compromise of the confidentiality, integrity, or availability of information expressed as a value of low, moderate or high.', 'kb-doc-14-nist-sp-800-53-p431-3', 0, 32, '14-nist-sp-800-53', 'retrieved', '6397870381E5FEE0A8C4D6F18653ABD9FEDCEF50E1978E6919BCF7114C997466', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
