INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p431-4', 'doc-14-nist-sp-800-53', '', 431, 'incident [FISMA] An occurrence that actually or imminently jeopardizes, without lawful authority, the confidentiality, integrity, or availability of information or an information system; or constitutes a violation or imminent threat of violation of law, security policies, security procedures, or acceptable use policies.', 'kb-doc-14-nist-sp-800-53-p431-4', 0, 42, '14-nist-sp-800-53', 'retrieved', 'EC28F36A33B7D94AAE97EFAACD2D423803DCD15E6DD26597F840562316322D80', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
