VALUES ('doc-14-nist-sp-800-53-p431-5', 'doc-14-nist-sp-800-53', '', 431, 'industrial control system [SP 800-82] General term that encompasses several types of control systems, including supervisory control and data acquisition (SCADA) systems, distributed control systems (DCS), and other control system configurations such as programmable logic controllers (PLC) found in the industrial sectors and critical infrastructures.', 'kb-doc-14-nist-sp-800-53-p431-5', 0, 45, '14-nist-sp-800-53', 'retrieved', 'B335212A00B5D53EC2D2C5A5315D9FADC678BAC1E1EB31535FFD61F226603A81', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
