INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p431-6', 'doc-14-nist-sp-800-53', '', 431, 'An industrial control system consists of combinations of control components (e.g., electrical, mechanical, hydraulic, pneumatic) that act together to achieve an industrial objective (e.g., manufacturing, transportation of matter or energy).', 'kb-doc-14-nist-sp-800-53-p431-6', 0, 30, '14-nist-sp-800-53', 'retrieved', 'C0A9BF2ADE2B20D6F9368A63E646C62A59D4B80675AEAC70B774AA38033D157A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
