VALUES ('doc-14-nist-sp-800-53-p431-7', 'doc-14-nist-sp-800-53', '', 431, 'information [OMB A-130] Any communication or representation of knowledge such as facts, data, or opinions in any medium or form, including textual, numerical, graphic, cartographic, narrative, electronic, or audiovisual forms.', 'kb-doc-14-nist-sp-800-53-p431-7', 0, 30, '14-nist-sp-800-53', 'retrieved', 'A643F84166A1AF8C4CD643706A84F34C64F365DAA2621F0B925AECE641950F34', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
