VALUES ('doc-14-nist-sp-800-53-p431-10', 'doc-14-nist-sp-800-53', '', 431, 'information owner [SP 800-37] Official with statutory or operational authority for specified information and responsibility for establishing the controls for its generation, collection, processing, dissemination, and disposal.', 'kb-doc-14-nist-sp-800-53-p431-10', 0, 27, '14-nist-sp-800-53', 'retrieved', '5E22BA0E964A172BBC08A2B4E4EEFFCD761442EBAF91ED2FF6692AC63335857E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
