VALUES ('doc-14-nist-sp-800-53-p431-12', 'doc-14-nist-sp-800-53', '', 431, 'information security [OMB A-130] The protection of information and systems from unauthorized access, use, disclosure, disruption, modification, or destruction in order to provide confidentiality, integrity, and availability.', 'kb-doc-14-nist-sp-800-53-p431-12', 0, 27, '14-nist-sp-800-53', 'retrieved', '7916338C28DE4958EDF83033D16D4EEF8528D1FE9D3FFE35CBBE970F1F17D0CE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
