VALUES ('doc-14-nist-sp-800-53-p431-13', 'doc-14-nist-sp-800-53', '', 431, 'information security architecture [OMB A-130] An embedded, integral part of the enterprise architecture that describes the structure and behavior of the enterprise security processes, security systems, personnel and organizational subunits, showing their alignment with the enterprise’s mission and strategic plans.', 'kb-doc-14-nist-sp-800-53-p431-13', 0, 40, '14-nist-sp-800-53', 'retrieved', 'F8E07F622BCDD56688573DA97DB42B738A008F266B14F5CEC111A5B63E4F2060', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
