VALUES ('doc-14-nist-sp-800-53-p432-2', 'doc-14-nist-sp-800-53', '', 432, 'information security policy [CNSSI 4009] Aggregate of directives, regulations, rules, and practices that prescribes how an organization manages, protects, and distributes information.', 'kb-doc-14-nist-sp-800-53-p432-2', 0, 22, '14-nist-sp-800-53', 'retrieved', '90581FEB8C751F648F07363EEF2A65C4B4CD6C82E005F3D1C2C38ABD79EF9820', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
