VALUES ('doc-14-nist-sp-800-53-p432-4', 'doc-14-nist-sp-800-53', '', 432, 'information security risk [SP 800-30] The risk to organizational operations (including mission, functions, image, reputation), organizational assets, individuals, other organizations, and the Nation due to the potential for unauthorized access, use, disclosure, disruption, modification, or destruction of information and/or systems.', 'kb-doc-14-nist-sp-800-53-p432-4', 0, 40, '14-nist-sp-800-53', 'retrieved', 'A832D1AAE73D7CACF3F920C6FF64A6A36CC1995C5B617C65E17061A6AB358C12', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
