INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-2', 'doc-14-nist-sp-800-53', '', 433, 'information type [FIPS 199] A specific category of information (e.g., privacy, medical, proprietary, financial, investigative, contractor-sensitive, security management) defined by an organization or in some instances, by a specific law, Executive Order, directive, policy, or regulation.', 'kb-doc-14-nist-sp-800-53-p433-2', 0, 36, '14-nist-sp-800-53', 'retrieved', 'E74BB5FD69BB459DDB26C1ACC0B3CB71DD6D2F1565B2091BA4CA3EC8A44607EB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-3', 'doc-14-nist-sp-800-53', '', 433, 'insider [CNSSI 4009, Adapted] Any person with authorized access to any organizational resource, to include personnel, facilities, information, equipment, networks, or systems.', 'kb-doc-14-nist-sp-800-53-p433-3', 0, 22, '14-nist-sp-800-53', 'retrieved', 'F0CFA0F59B836F4E732718066B25B23FA559BC0E594DA38993C93087DCD973D5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-4', 'doc-14-nist-sp-800-53', '', 433, 'insider threat [CNSSI 4009, Adapted] The threat that an insider will use her/his authorized access, wittingly or unwittingly, to do harm to the security of organizational operations and assets, individuals, other organizations, and the Nation. This threat can include damage through espionage, terrorism, unauthorized disclosure of national security information, or through the loss or degradation of organizational resources or capabilities.', 'kb-doc-14-nist-sp-800-53-p433-4', 0, 60, '14-nist-sp-800-53', 'retrieved', '2F8268AFE113B6B12E17D03589990EFEDF0F9710AC8D96F42C7E7E460A2CE9A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-5', 'doc-14-nist-sp-800-53', '', 433, 'insider threat program [CNSSI 4009, Adapted] A coordinated collection of capabilities authorized by the organization and used to deter, detect, and mitigate the unauthorized disclosure of information.', 'kb-doc-14-nist-sp-800-53-p433-5', 0, 27, '14-nist-sp-800-53', 'retrieved', '300B0E2D1FF1D23241C7F46F683C1B07AAEB89942CB9F41CEC4D39854449F80F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-6', 'doc-14-nist-sp-800-53', '', 433, 'interface [CNSSI 4009] Common boundary between independent systems or modules where interactions take place.', 'kb-doc-14-nist-sp-800-53-p433-6', 0, 14, '14-nist-sp-800-53', 'retrieved', '652BB80E086D5097FAD786E0C3458CEAC63C004A7E8A7FDD889F05CE8A7A8092', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
