INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-7', 'doc-14-nist-sp-800-53', '', 433, 'integrity [FISMA] Guarding against improper information modification or destruction, and includes ensuring information non-repudiation and authenticity.', 'kb-doc-14-nist-sp-800-53-p433-7', 0, 16, '14-nist-sp-800-53', 'retrieved', '44D6FC311A8944C0D66F03B90E6E0E91B5D1E099185F235CFE6409F1C49704A4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
