INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-8', 'doc-14-nist-sp-800-53', '', 433, 'internal network A network where the establishment, maintenance, and provisioning of security controls are under the direct control of organizational employees or contractors. Cryptographic encapsulation or similar security technology implemented between organization-controlled endpoints provides the same effect (at least regarding confidentiality and integrity). An internal network is typically organization-owned yet may be organization-controlled while not being organization-owned.', 'kb-doc-14-nist-sp-800-53-p433-8', 0, 57, '14-nist-sp-800-53', 'retrieved', 'A46E891B567A67C18C4E8BEC4DF5631D5BC4FD172F214011835C12FE04FD3859', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-10', 'doc-14-nist-sp-800-53', '', 433, 'least privilege [CNSSI 4009] The principle that a security architecture is designed so that each entity is granted the minimum system resources and authorizations that the entity needs to perform its function.', 'kb-doc-14-nist-sp-800-53-p433-10', 0, 32, '14-nist-sp-800-53', 'retrieved', 'A0BAE0D6EFB5C69300921C2701D33BCE9B45B8BE404372450167F4AA43C03F0F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p433-11', 'doc-14-nist-sp-800-53', '', 433, 'local access Access to an organizational system by a user (or process acting on behalf of a user) communicating through a direct connection without the use of a network.', 'kb-doc-14-nist-sp-800-53-p433-11', 0, 29, '14-nist-sp-800-53', 'retrieved', '8CA7BA8F8AF9605C0A6CB82AA17F12FB4060891DA98CD590E70E4614896CEDE1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
