VALUES ('doc-14-nist-sp-800-53-p434-1', 'doc-14-nist-sp-800-53', '', 434, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A PAGE 407 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p434-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '549303D57B79060DA38B2AAAE125C38AED16C9D9A53ACA041640E67A2EACDA6E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
