INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-2', 'doc-14-nist-sp-800-53', '', 434, 'logical access control system An automated system that controls an individual’s ability to access one or more computer system resources, such as a workstation, network, application, or database. A logical access control system requires the validation of an individual’s identity through some mechanism, such as a PIN, card, biometric, or other token. It has the capability to assign different access privileges to different individuals depending on their roles and responsibilities in an organization.', 'kb-doc-14-nist-sp-800-53-p434-2', 0, 73, '14-nist-sp-800-53', 'retrieved', 'DDA1CC49D5FEA33D0814DB98DEEE01BA7BE42C6E9CC8006F80715B403982437E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-3', 'doc-14-nist-sp-800-53', '', 434, 'low-impact system [FIPS 200] A system in which all three security objectives (i.e., confidentiality, integrity, and availability) are assigned a FIPS Publication 199 potential impact value of low.', 'kb-doc-14-nist-sp-800-53-p434-3', 0, 28, '14-nist-sp-800-53', 'retrieved', 'CDB47B264788614196AE387BFCF7C7A4C378CE65E0F8E23D62D307A8104F209B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-4', 'doc-14-nist-sp-800-53', '', 434, 'malicious code Software or firmware intended to perform an unauthorized process that will have adverse impacts on the confidentiality, integrity, or availability of a system. A virus, worm, Trojan horse, or other code-based entity that infects a host. Spyware and some forms of adware are also examples of malicious code.', 'kb-doc-14-nist-sp-800-53-p434-4', 0, 50, '14-nist-sp-800-53', 'retrieved', 'D61A31284CDC90CBC31B0272835EFEAEEE13E7B528057DD4182B230C17CA82BE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-5', 'doc-14-nist-sp-800-53', '', 434, 'managed interface An interface within a system that provides boundary protection capabilities using automated mechanisms or devices.', 'kb-doc-14-nist-sp-800-53-p434-5', 0, 17, '14-nist-sp-800-53', 'retrieved', 'E9EDBDBF9A2A12864C85113C63B27A339AF34985EB136421BA9D8C4BC565FC01', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-6', 'doc-14-nist-sp-800-53', '', 434, 'mandatory access control An access control policy that is uniformly enforced across all subjects and objects within a system. A subject that has been granted access to information is constrained from: passing the information to unauthorized subjects or objects; granting its privileges to other subjects; changing one or more security attributes on subjects, objects, the system, or system components; choosing the security attributes to be associated with newly created or modified objects; or changing the rules for governing access control. Organization-defined subjects may explicitly be granted organization-defined privileges (i.e., they are trusted subjects) such that they are not limited by some or all of the above constraints. Mandatory access control is considered a type of nondiscretionary access control.', 'kb-doc-14-nist-sp-800-53-p434-6', 0, 118, '14-nist-sp-800-53', 'retrieved', 'E5D9E7E44591F51646E128C8E31C13B3F75D1201ED1ACDF70EB38ED638C26D14', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-8', 'doc-14-nist-sp-800-53', '', 434, 'matching agreement [OMB A-108] A written agreement between a recipient agency and a source agency (or a non-Federal agency) that is required by the Privacy Act for parties engaging in a matching program.', 'kb-doc-14-nist-sp-800-53-p434-8', 0, 33, '14-nist-sp-800-53', 'retrieved', 'D0F2E77A074535CC91D4AE4BC6CA211D9AB01C77D0E05D151E5897D721B90F9C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
