INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-9', 'doc-14-nist-sp-800-53', '', 434, 'media [FIPS 200] Physical devices or writing surfaces including magnetic tapes, optical disks, magnetic disks, Large-Scale Integration memory chips, and printouts (but excluding display media) onto which information is recorded, stored, or printed within a system.', 'kb-doc-14-nist-sp-800-53-p434-9', 0, 36, '14-nist-sp-800-53', 'retrieved', '30FA0BA83100F75DAE58C0D4B6A348977975127A3857099D8216CC2300927B63', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
