INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p434-10', 'doc-14-nist-sp-800-53', '', 434, 'metadata Information that describes the characteristics of data, including structural metadata that describes data structures (i.e., data format, syntax, semantics) and descriptive metadata that describes data contents (i.e., security labels).', 'kb-doc-14-nist-sp-800-53-p434-10', 0, 30, '14-nist-sp-800-53', 'retrieved', '3952156C74FE10C9993024AD589C46F1A083339AE9D7836A3A652A33CA308A52', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
