VALUES ('doc-14-nist-sp-800-53-p435-3', 'doc-14-nist-sp-800-53', '', 435, 'mobile code technologies Software technologies that provide the mechanisms for the production and use of mobile code.', 'kb-doc-14-nist-sp-800-53-p435-3', 0, 17, '14-nist-sp-800-53', 'retrieved', '4642DD2CE3D88B7433700D6E4A790501681235921BB7F336B1449EB44F3D82E8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
