INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p435-6', 'doc-14-nist-sp-800-53', '', 435, 'multi-factor authentication [SP 800-63-3] An authentication system or an authenticator that requires more than one authentication factor for successful authentication.', 'kb-doc-14-nist-sp-800-53-p435-6', 0, 20, '14-nist-sp-800-53', 'retrieved', 'B009C97A4B567F82F3C301E9CC676AB858F204AC62CF8D42AF7FF8EA874F45E1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
