INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p435-7', 'doc-14-nist-sp-800-53', '', 435, 'Multi-factor authentication can be performed using a single authenticator that provides more than one factor or by a combination of authenticators that provide different factors.', 'kb-doc-14-nist-sp-800-53-p435-7', 0, 25, '14-nist-sp-800-53', 'retrieved', '5700ADBB5769C5529A83FA4E3794E5A2D255C96425840817474FD7C8975C3D7D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
