INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p435-8', 'doc-14-nist-sp-800-53', '', 435, 'The three authentication factors are something you know, something you have, and something you are.', 'kb-doc-14-nist-sp-800-53-p435-8', 0, 15, '14-nist-sp-800-53', 'retrieved', '193C9EA7160C097523AB28AC93B451DF62E2089BC92DAC9C9B31E67BBE800617', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
