VALUES ('doc-14-nist-sp-800-53-p435-10', 'doc-14-nist-sp-800-53', '', 435, 'multilevel security [CNSSI 4009] Concept of processing information with different classifications and categories that simultaneously permits access by users with different security clearances and denies access to users who lack authorization.', 'kb-doc-14-nist-sp-800-53-p435-10', 0, 31, '14-nist-sp-800-53', 'retrieved', 'C95D5D36EF452AFFC87F3CDCB58B12B0D5FC6065D7CAEA4B969442E716065824', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
