VALUES ('doc-14-nist-sp-800-53-p435-11', 'doc-14-nist-sp-800-53', '', 435, 'multiple security levels [CNSSI 4009] Capability of a system that is trusted to contain, and maintain separation between, resources (particularly stored data) of different security domains.', 'kb-doc-14-nist-sp-800-53-p435-11', 0, 26, '14-nist-sp-800-53', 'retrieved', 'A9126F685E15C78B022F32753B370AF0A22F4335ED1A42762DA61AA923D5B388', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
