VALUES ('doc-14-nist-sp-800-53-p436-1', 'doc-14-nist-sp-800-53', '', 436, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A PAGE 409 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p436-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '597131BE544AD5DBB779008DEE44275D2BCEEFD9F9CE87C0F2C94D381F597299', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
