VALUES ('doc-14-nist-sp-800-53-p436-5', 'doc-14-nist-sp-800-53', '', 436, 'network access Access to a system by a user (or a process acting on behalf of a user) communicating through a network, including a local area network, a wide area network, and the Internet.', 'kb-doc-14-nist-sp-800-53-p436-5', 0, 34, '14-nist-sp-800-53', 'retrieved', '1859D6E5823F2708499E77D6D2049A7C3338E70083C2E74B13C4141AB199CA24', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
