INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p436-6', 'doc-14-nist-sp-800-53', '', 436, 'nonce [SP 800-63-3] A value used in security protocols that is never repeated with the same key. For example, nonces used as challenges in challenge- response authentication protocols are not repeated until the authentication keys are changed. Otherwise, there is a possibility of a replay attack.', 'kb-doc-14-nist-sp-800-53-p436-6', 0, 46, '14-nist-sp-800-53', 'retrieved', '1ABDF97756E126C7A3D40AB39EA8B70911F9CC901692AED4BEBC3D45F8577FE7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
