VALUES ('doc-14-nist-sp-800-53-p436-8', 'doc-14-nist-sp-800-53', '', 436, 'nonlocal maintenance Maintenance activities conducted by individuals who communicate through either an internal or external network.', 'kb-doc-14-nist-sp-800-53-p436-8', 0, 16, '14-nist-sp-800-53', 'retrieved', '1197DB929F9D48FE3B39691FE003665F49E220F720093FD9894CED826A04AE55', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
