VALUES ('doc-14-nist-sp-800-53-p436-9', 'doc-14-nist-sp-800-53', '', 436, 'non-organizational user A user who is not an organizational user (including public users).', 'kb-doc-14-nist-sp-800-53-p436-9', 0, 13, '14-nist-sp-800-53', 'retrieved', '89E9CDC7EF56D28F7A267FF27A410701D61F5EBF5918FFCCA113E147FA28859B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
