VALUES ('doc-14-nist-sp-800-53-p436-10', 'doc-14-nist-sp-800-53', '', 436, 'non-repudiation Protection against an individual who falsely denies having performed a certain action and provides the capability to determine whether an individual took a certain action, such as creating information, sending a message, approving information, or receiving a message.', 'kb-doc-14-nist-sp-800-53-p436-10', 0, 39, '14-nist-sp-800-53', 'retrieved', 'BE396253D6ECF590460BF649B3205A1FF1CEEAF9CAF446DAA07F4D2647DD93EB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
