VALUES ('doc-14-nist-sp-800-53-p436-11', 'doc-14-nist-sp-800-53', '', 436, 'NSA-approved cryptography Cryptography that consists of an approved algorithm, an implementation that has been approved for the protection of classified information and/or controlled unclassified information in a specific environment, and a supporting key management infrastructure.', 'kb-doc-14-nist-sp-800-53-p436-11', 0, 35, '14-nist-sp-800-53', 'retrieved', '080398170EDAF1CE8D5394CB303720BCA9C22256596F3F4F355AC59B8931288B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
