VALUES ('doc-14-nist-sp-800-53-p437-2', 'doc-14-nist-sp-800-53', '', 437, 'object Passive system-related entity, including devices, files, records, tables, processes, programs, and domains that contain or receive information. Access to an object (by a subject) implies access to the information it contains. See subject.', 'kb-doc-14-nist-sp-800-53-p437-2', 0, 34, '14-nist-sp-800-53', 'retrieved', 'E1FBD715E89C8B54A625C963EEC89BE527EA545440AA655AE14FBA0058317DE1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
