VALUES ('doc-14-nist-sp-800-53-p437-4', 'doc-14-nist-sp-800-53', '', 437, 'Systematic and proven process by which potential adversaries can be denied information about capabilities and intentions by identifying, controlling, and protecting generally unclassified evidence of the planning and execution of sensitive activities.', 'kb-doc-14-nist-sp-800-53-p437-4', 0, 32, '14-nist-sp-800-53', 'retrieved', 'F389C95E670CFEA2441E615346F309FD5DE4FE32CDF6497F468BFE2649226C8D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
