INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p437-5', 'doc-14-nist-sp-800-53', '', 437, 'The process involves five steps: identification of critical information, analysis of threats, analysis of vulnerabilities, assessment of risks, and application of appropriate countermeasures.', 'kb-doc-14-nist-sp-800-53-p437-5', 0, 23, '14-nist-sp-800-53', 'retrieved', 'E8D1CCA1DB2BF66D47E7FD92141025A5F102240346D2BD1628812C2430C6D197', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
