VALUES ('doc-14-nist-sp-800-53-p437-6', 'doc-14-nist-sp-800-53', '', 437, 'organization [FIPS 200, Adapted] An entity of any size, complexity, or positioning within an organizational structure, including federal agencies, private enterprises, academic institutions, state, local, or tribal governments, or as appropriate, any of their operational elements.', 'kb-doc-14-nist-sp-800-53-p437-6', 0, 36, '14-nist-sp-800-53', 'retrieved', '157954EAF78B9D7FEDE2DB2201BA2F8F521549866E523279AD3CFCAE1D092418', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
