INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p437-7', 'doc-14-nist-sp-800-53', '', 437, 'organization-defined control parameter The variable part of a control or control enhancement that is instantiated by an organization during the tailoring process by either assigning an organization-defined value or selecting a value from a predefined list provided as part of the control or control enhancement. See assignment operation and selection operation.', 'kb-doc-14-nist-sp-800-53-p437-7', 0, 51, '14-nist-sp-800-53', 'retrieved', 'C853A45E09BF768B801618A3BEEC67CE28ADA07A728ECD47C5836452EF7C5D63', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
