INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p437-8', 'doc-14-nist-sp-800-53', '', 437, 'organizational user An organizational employee or an individual whom the organization deems to have equivalent status of an employee, including a contractor, guest researcher, or individual detailed from another organization. Policies and procedures for granting the equivalent status of employees to individuals may include need-to-know, relationship to the organization, and citizenship.', 'kb-doc-14-nist-sp-800-53-p437-8', 0, 51, '14-nist-sp-800-53', 'retrieved', '3028629344B65906FEA47415F73614C745EEB4838731346D5FDF5F326E1CA275', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
