INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p437-9', 'doc-14-nist-sp-800-53', '', 437, 'overlay [OMB A-130] A specification of security or privacy controls, control enhancements, supplemental guidance, and other supporting information employed during the tailoring process, that is intended to complement (and further refine) security control baselines. The overlay specification may be more stringent or less stringent than the original security control baseline specification and can be applied to multiple information systems.', 'kb-doc-14-nist-sp-800-53-p437-9', 0, 59, '14-nist-sp-800-53', 'retrieved', 'A34AAA08F147C39EB2B374FBB11849704C85FD9178B3221F352A7B6239ADBED1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
