INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p437-12', 'doc-14-nist-sp-800-53', '', 437, 'penetration testing A test methodology in which assessors, typically working under specific constraints, attempt to circumvent or defeat the security features of a system.', 'kb-doc-14-nist-sp-800-53-p437-12', 0, 24, '14-nist-sp-800-53', 'retrieved', 'F08E1EB28B90E292D9F2CECCA30FF26BFFD0F175E0F686A0D20A28C61E6765DA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
