INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-2', 'doc-14-nist-sp-800-53', '', 438, 'periods processing A mode of system operation in which information of different sensitivities is processed at distinctly different times by the same system with the system being properly purged or sanitized between periods.', 'kb-doc-14-nist-sp-800-53-p438-2', 0, 33, '14-nist-sp-800-53', 'retrieved', 'AA51E02E8A99E8CE52010C8BE2250F2E540A901EC0C480E9B8A3667C859A2E35', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
