INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-3', 'doc-14-nist-sp-800-53', '', 438, 'personally identifiable information [OMB A-130] Information that can be used to distinguish or trace an individual’s identity, either alone or when combined with other information that is linked or linkable to a specific individual.', 'kb-doc-14-nist-sp-800-53-p438-3', 0, 34, '14-nist-sp-800-53', 'retrieved', '3F594B527EF77BC20E6A4931D1186866AEBCB0EE8494A03F8982864689329A0B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
