INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-4', 'doc-14-nist-sp-800-53', '', 438, 'personally identifiable information processing [ISO/IEC 29100, Adapted] An operation or set of operations performed upon personally identifiable information that can include, but is not limited to, the collection, retention, logging, generation, transformation, use, disclosure, transfer, and disposal of personally identifiable information.', 'kb-doc-14-nist-sp-800-53-p438-4', 0, 41, '14-nist-sp-800-53', 'retrieved', '24006AB11F5496B4D231F420ABC1BC118B9F90B91CC512DEB83D6037ECCE4E2D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
