INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-5', 'doc-14-nist-sp-800-53', '', 438, 'personally identifiable information processing permissions The requirements for how personally identifiable information can be processed or the conditions under which personally identifiable information can be processed.', 'kb-doc-14-nist-sp-800-53-p438-5', 0, 26, '14-nist-sp-800-53', 'retrieved', '20CDE5F596224D7355DC22764EFA83954C0AFDBA537CA27615F98F687B970C48', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
