VALUES ('doc-14-nist-sp-800-53-p438-6', 'doc-14-nist-sp-800-53', '', 438, 'personnel security The discipline of assessing the conduct, integrity, judgment, loyalty, reliability, and stability of individuals for duties and responsibilities that require trustworthiness.', 'kb-doc-14-nist-sp-800-53-p438-6', 0, 23, '14-nist-sp-800-53', 'retrieved', '6D62391F6C2D342B81C5DD88470C79E46EB7F55911DACC02414C08570A197D25', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
