INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-7', 'doc-14-nist-sp-800-53', '', 438, 'physical access control system [SP 800-116] An electronic system that controls the ability of people or vehicles to enter a protected area by means of authentication and authorization at access control points.', 'kb-doc-14-nist-sp-800-53-p438-7', 0, 32, '14-nist-sp-800-53', 'retrieved', '91677E8F3BC3A5252EFABAD402EE5A31B8AF3C290AC38921EB1623DC873D771B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
