VALUES ('doc-14-nist-sp-800-53-p438-10', 'doc-14-nist-sp-800-53', '', 438, 'It details resources required to accomplish the elements of the plan, milestones for meeting the tasks, and the scheduled completion dates for the milestones.', 'kb-doc-14-nist-sp-800-53-p438-10', 0, 24, '14-nist-sp-800-53', 'retrieved', '509701EF539B92C242B26C915C8335D6295CB4591B221A884385BB8782C71192', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
