INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-11', 'doc-14-nist-sp-800-53', '', 438, 'portable storage device A system component that can communicate with and be added to or removed from a system or network and that is limited to data storage— including text, video, audio or image data— as its primary function (e.g., optical discs, external or removable hard drives, external or removable solid-state disk drives, magnetic or optical tapes, flash memory devices, flash memory cards, and other external or removable disks).', 'kb-doc-14-nist-sp-800-53-p438-11', 0, 69, '14-nist-sp-800-53', 'retrieved', '7E2A3CC58EEC0B5EEEC0FE60D93EC17DEDC13852978AC25E7B1DFB5AF6EBA20C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
