INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-12', 'doc-14-nist-sp-800-53', '', 438, 'potential impact [FIPS 199] The loss of confidentiality, integrity, or availability could be expected to have a limited adverse effect (FIPS Publication 199 low); a serious adverse effect (FIPS Publication 199 moderate); or a severe or catastrophic adverse effect (FIPS Publication 199 high) on organizational operations, organizational assets, or individuals.', 'kb-doc-14-nist-sp-800-53-p438-12', 0, 50, '14-nist-sp-800-53', 'retrieved', '8FA9C2AF7D00A047BE5A9735AF7FA4C926D973E2EDF18DAB333083D01B7EDF74', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
