INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p438-13', 'doc-14-nist-sp-800-53', '', 438, 'privacy architecture [SP 800-37] An embedded, integral part of the enterprise architecture that describes the structure and behavior for an enterprise’s privacy protection processes, technical measures, personnel and organizational sub-units, showing their alignment with the enterprise’s mission and strategic plans.', 'kb-doc-14-nist-sp-800-53-p438-13', 0, 40, '14-nist-sp-800-53', 'retrieved', 'BBD27D3E283F31000C877F959AD24F0C310A7759E93CB6A2BC65A78CBDF8B13E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
