INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p439-2', 'doc-14-nist-sp-800-53', '', 439, 'privacy control [OMB A-130] The administrative, technical, and physical safeguards employed within an agency to ensure compliance with applicable privacy requirements and manage privacy risks.', 'kb-doc-14-nist-sp-800-53-p439-2', 0, 25, '14-nist-sp-800-53', 'retrieved', 'A0666094EE56FEE8ABADA013A3816DFAF90BA76DCAEFF4E87B086C5C12719008', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
