INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p439-3', 'doc-14-nist-sp-800-53', '', 439, 'privacy control baseline The set of privacy controls selected based on the privacy selection criteria that provide a starting point for the tailoring process.', 'kb-doc-14-nist-sp-800-53-p439-3', 0, 24, '14-nist-sp-800-53', 'retrieved', 'FC45F6CC270BB606E91A76110574D5C1132DCF76A82C19B8436636105E65EE87', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
