VALUES ('doc-14-nist-sp-800-53-p439-8', 'doc-14-nist-sp-800-53', '', 439, 'privileged account A system account with the authorizations of a privileged user.', 'kb-doc-14-nist-sp-800-53-p439-8', 0, 12, '14-nist-sp-800-53', 'retrieved', 'A590E1BBA36583125629DD8065BD473B99BA861B8E8895F6394CA0E12C9566DE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
