VALUES ('doc-14-nist-sp-800-53-p439-9', 'doc-14-nist-sp-800-53', '', 439, 'privileged command A human-initiated command executed on a system that involves the control, monitoring, or administration of the system, including security functions and associated security-relevant information.', 'kb-doc-14-nist-sp-800-53-p439-9', 0, 26, '14-nist-sp-800-53', 'retrieved', '7B279DD81CEAEF53FBC5D6651BB7705D78DF9E336CF16ABD25B5842DAE53CB7A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
