VALUES ('doc-14-nist-sp-800-53-p439-10', 'doc-14-nist-sp-800-53', '', 439, 'privileged user [CNSSI 4009] A user that is authorized (and therefore, trusted) to perform security-relevant functions that ordinary users are not authorized to perform.', 'kb-doc-14-nist-sp-800-53-p439-10', 0, 24, '14-nist-sp-800-53', 'retrieved', '3EC79B3C626975853C570E9A19EDA911B6D9C8A0AE1ECA8506190687C06443C3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
