VALUES ('doc-14-nist-sp-800-53-p440-2', 'doc-14-nist-sp-800-53', '', 440, 'protected distribution system [CNSSI 4009] Wire line or fiber optic system that includes adequate safeguards and/or countermeasures (e.g., acoustic, electric, electromagnetic, and physical) to permit its use for the transmission of unencrypted information through an area of lesser classification or control.', 'kb-doc-14-nist-sp-800-53-p440-2', 0, 41, '14-nist-sp-800-53', 'retrieved', '3C53CE18D587AFE26F4A5EFD8BC3062CB21613904073C6A89FADC5B7F11355EC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
