INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p440-3', 'doc-14-nist-sp-800-53', '', 440, 'provenance The chronology of the origin, development, ownership, location, and changes to a system or system component and associated data. It may also include the personnel and processes used to interact with or make modifications to the system, component, or associated data.', 'kb-doc-14-nist-sp-800-53-p440-3', 0, 42, '14-nist-sp-800-53', 'retrieved', '0AB5B901E5F56FE661FF73DDE347A70D3D6161532D2ED856CE3438D251D950ED', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
