VALUES ('doc-14-nist-sp-800-53-p440-4', 'doc-14-nist-sp-800-53', '', 440, 'public key infrastructure [CNSSI 4009] The architecture, organization, techniques, practices, and procedures that collectively support the implementation and operation of a certificate-based public key cryptographic system.', 'kb-doc-14-nist-sp-800-53-p440-4', 0, 26, '14-nist-sp-800-53', 'retrieved', 'A71B28A12427FAFB55FE4EDE4409A9AAE36E954FDC9383A81728333996D55E2B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
