VALUES ('doc-14-nist-sp-800-53-p440-6', 'doc-14-nist-sp-800-53', '', 440, 'purge [SP 800-88] A method of sanitization that applies physical or logical techniques that render target data recovery infeasible using state of the art laboratory techniques.', 'kb-doc-14-nist-sp-800-53-p440-6', 0, 26, '14-nist-sp-800-53', 'retrieved', '604D0A9E3572C8EBCAD0DF81E2BBB911335457F890980FB113EC65A117E88192', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
