INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p440-7', 'doc-14-nist-sp-800-53', '', 440, 'reciprocity [SP 800-37] Agreement among participating organizations to accept each other’s security assessments to reuse system resources and/or to accept each other’s assessed security posture to share information.', 'kb-doc-14-nist-sp-800-53-p440-7', 0, 28, '14-nist-sp-800-53', 'retrieved', '3CD9CD90E4ABFF1FD0F8350CDEAECFA1B882CD0A78008531EFB5C23EDB0E7AB3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
