INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p440-8', 'doc-14-nist-sp-800-53', '', 440, 'records [OMB A-130] All recorded information, regardless of form or characteristics, made or received by a Federal agency under Federal law or in connection with the transaction of public business and preserved or appropriate for preservation by that agency or its legitimate successor as evidence of the organization, functions, policies, decisions, procedures, operations, or other activities of the United States Government or because of the informational value of data in them.', 'kb-doc-14-nist-sp-800-53-p440-8', 0, 71, '14-nist-sp-800-53', 'retrieved', '60031775F5B47C83767CFDAA6E58EF0AEC20473750E578E6EEDAD16038099EC7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
