INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p440-9', 'doc-14-nist-sp-800-53', '', 440, 'red team exercise An exercise, reflecting real-world conditions that is conducted as a simulated adversarial attempt to compromise organizational missions or business processes and to provide a comprehensive assessment of the security capabilities of an organization and its systems.', 'kb-doc-14-nist-sp-800-53-p440-9', 0, 39, '14-nist-sp-800-53', 'retrieved', '99B1B2C7066BE370B29520E24B173895DFC83ED5BED373EAAB12FF48D89FB672', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
