VALUES ('doc-14-nist-sp-800-53-p441-2', 'doc-14-nist-sp-800-53', '', 441, 'regrader [CNSSI 4009] A trusted process explicitly authorized to re-classify and re-label data in accordance with a defined policy exception. Untrusted or unauthorized processes are such actions by the security policy.', 'kb-doc-14-nist-sp-800-53-p441-2', 0, 31, '14-nist-sp-800-53', 'retrieved', '9B66A5BFFBDB79E07F647799A5E6DDCAE42C6CE3F6472E768F7AB440C4B019E6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
