VALUES ('doc-14-nist-sp-800-53-p441-3', 'doc-14-nist-sp-800-53', '', 441, 'remote access Access to an organizational system by a user (or a process acting on behalf of a user) communicating through an external network.', 'kb-doc-14-nist-sp-800-53-p441-3', 0, 24, '14-nist-sp-800-53', 'retrieved', '71AA4F1425FA87D16D7D0C2D83E7B414FF2F879DF9CF41EC1F1CD789EFD94C2A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
