VALUES ('doc-14-nist-sp-800-53-p441-4', 'doc-14-nist-sp-800-53', '', 441, 'remote maintenance Maintenance activities conducted by individuals communicating through an external network.', 'kb-doc-14-nist-sp-800-53-p441-4', 0, 12, '14-nist-sp-800-53', 'retrieved', 'B93EEB173F85D647D59F877D0D57056E284663C57C2898F258E562AD4B34B83C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
