VALUES ('doc-14-nist-sp-800-53-p441-5', 'doc-14-nist-sp-800-53', '', 441, 'replay attack [SP 800-63-3] An attack in which the Attacker is able to replay previously captured messages (between a legitimate Claimant and a Verifier) to masquerade as that Claimant to the Verifier or vice versa.', 'kb-doc-14-nist-sp-800-53-p441-5', 0, 35, '14-nist-sp-800-53', 'retrieved', '0C7F6442A592389835E5E0FE733D68F44E47F11E019C8350F5C710161A584095', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
