VALUES ('doc-14-nist-sp-800-53-p441-6', 'doc-14-nist-sp-800-53', '', 441, 'replay resistance Protection against the capture of transmitted authentication or access control information and its subsequent retransmission with the intent of producing an unauthorized effect or gaining unauthorized access.', 'kb-doc-14-nist-sp-800-53-p441-6', 0, 29, '14-nist-sp-800-53', 'retrieved', 'D040954002722D881B6745FB0C3F9AC31C46C77B25F30719AEDA3E57C0045070', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
