INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p441-7', 'doc-14-nist-sp-800-53', '', 441, 'resilience [OMB A-130] The ability of an information system to operate under adverse conditions or stress, even if in a degraded or debilitated state, while maintaining essential operational capabilities, and to recover to an effective operational posture in a time frame consistent with mission needs.', 'kb-doc-14-nist-sp-800-53-p441-7', 0, 45, '14-nist-sp-800-53', 'retrieved', '0D4407A913A86D9E958C7BE1FA54EF744C11F30D0C4A067FEE3A14A2A67EE9B6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
