INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p441-8', 'doc-14-nist-sp-800-53', '', 441, 'restricted data [ATOM54] All data concerning (i) design, manufacture, or utilization of atomic weapons; (ii) the production of special nuclear material; or (iii) the use of special nuclear material in the production of energy, but shall not include data declassified or removed from the Restricted Data category pursuant to Section 142 [of the Atomic Energy Act of 1954].', 'kb-doc-14-nist-sp-800-53-p441-8', 0, 58, '14-nist-sp-800-53', 'retrieved', 'FB473492259CE4F57DF0D9EDF3AE9872C5946E43B4CEF5D8C1E1D81B7A93A69C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p441-9', 'doc-14-nist-sp-800-53', '', 441, 'risk [OMB A-130] A measure of the extent to which an entity is threatened by a potential circumstance or event, and typically is a function of: (i) the adverse impact, or magnitude of harm, that would arise if the circumstance or event occurs; and (ii) the likelihood of occurrence.', 'kb-doc-14-nist-sp-800-53-p441-9', 0, 49, '14-nist-sp-800-53', 'retrieved', '542EDA971254E838FAF9F2FEB75247F6DA77873A78B0759D26EB9C85C46957F0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
