INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p441-11', 'doc-14-nist-sp-800-53', '', 441, 'The process of identifying risks to organizational operations (including mission, functions, image, reputation), organizational assets, individuals, other organizations, and the Nation, resulting from the operation of a system.', 'kb-doc-14-nist-sp-800-53-p441-11', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F1076DB51C4E147AE486E70654D352DD9855C8F3D78F737E11BC8826647FFA55', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
