INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p441-12', 'doc-14-nist-sp-800-53', '', 441, 'Risk management includes threat and vulnerability analyses as well as analyses of adverse effects on individuals arising from information processing and considers mitigations provided by security and privacy controls planned or in place. Synonymous with risk analysis.', 'kb-doc-14-nist-sp-800-53-p441-12', 0, 37, '14-nist-sp-800-53', 'retrieved', 'DD6562A108C9ECA3E0394A758F150398F301A8090C7AE19130E3511C01CEA399', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
