VALUES ('doc-14-nist-sp-800-53-p442-6', 'doc-14-nist-sp-800-53', '', 442, 'risk tolerance [SP 800-39] The level of risk or the degree of uncertainty that is acceptable to an organization.', 'kb-doc-14-nist-sp-800-53-p442-6', 0, 19, '14-nist-sp-800-53', 'retrieved', 'C65A9B2D60F5E97E59E82E20084A5D33C893DA588F1BFE47F02CFC1A5BF4F36A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
