INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p442-7', 'doc-14-nist-sp-800-53', '', 442, 'role-based access control Access control based on user roles (i.e., a collection of access authorizations that a user receives based on an explicit or implicit assumption of a given role). Role permissions may be inherited through a role hierarchy and typically reflect the permissions needed to perform defined functions within an organization. A given role may apply to a single individual or to several individuals.', 'kb-doc-14-nist-sp-800-53-p442-7', 0, 65, '14-nist-sp-800-53', 'retrieved', 'BCA66CFAB4A88A1B65B6C98EF2EA3090EA02C35DC3DFFD8EE8A61187B593CEBA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
