INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p442-9', 'doc-14-nist-sp-800-53', '', 442, 'sanitization [SP 800-88] A process to render access to target data on the media infeasible for a given level of effort. Clear, purge, and destroy are actions that can be taken to sanitize media.', 'kb-doc-14-nist-sp-800-53-p442-9', 0, 34, '14-nist-sp-800-53', 'retrieved', '5AAA17382E833F9623C0D768A6B0C377B85459B43ECDF9B6F071C3B04CC6CAA1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
