VALUES ('doc-14-nist-sp-800-53-p442-10', 'doc-14-nist-sp-800-53', '', 442, 'scoping considerations A part of tailoring guidance that provides organizations with specific considerations on the applicability and implementation of security and privacy controls in the control baselines.', 'kb-doc-14-nist-sp-800-53-p442-10', 0, 27, '14-nist-sp-800-53', 'retrieved', '3D234E88E03025355BA39CA5825AE834C295ED1345AC02BB9D48A2635BD8CD3B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
