VALUES ('doc-14-nist-sp-800-53-p442-11', 'doc-14-nist-sp-800-53', '', 442, 'Considerations include policy or regulatory, technology, physical infrastructure, system component allocation, public access, scalability, common control, operational or environmental, and security objective.', 'kb-doc-14-nist-sp-800-53-p442-11', 0, 22, '14-nist-sp-800-53', 'retrieved', '8538E796D76BDAAE69294A5F93A30B43FE0700C35100B5745BDD6067C784AE4B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
