INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p443-3', 'doc-14-nist-sp-800-53', '', 443, 'A condition that results from the establishment and maintenance of protective measures that enable an organization to perform its mission or critical functions despite risks posed by threats to its use of systems. Protective measures may involve a combination of deterrence, avoidance, prevention, detection, recovery, and correction that should form part of the organization’s risk management approach.', 'kb-doc-14-nist-sp-800-53-p443-3', 0, 57, '14-nist-sp-800-53', 'retrieved', 'B471DA67CC3810F0CA889529FB38327E0E710B85C4D5FFD5905B4F384F0E2BC4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
