INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p443-4', 'doc-14-nist-sp-800-53', '', 443, 'security attribute An abstraction that represents the basic properties or characteristics of an entity with respect to safeguarding information. Typically associated with internal data structures— including records, buffers, and files within the system— and used to enable the implementation of access control and flow control policies; reflect special dissemination, handling or distribution instructions; or support other aspects of the information security policy.', 'kb-doc-14-nist-sp-800-53-p443-4', 0, 62, '14-nist-sp-800-53', 'retrieved', '6598C936A778DF609BFA37F43FD665BAEEBDFF348FFB4C92D8A6E113906657BE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
