INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p443-5', 'doc-14-nist-sp-800-53', '', 443, 'security categorization The process of determining the security category for information or a system. Security categorization methodologies are described in CNSS Instruction 1253 for national security systems and in FIPS Publication 199 for other than national security systems.', 'kb-doc-14-nist-sp-800-53-p443-5', 0, 38, '14-nist-sp-800-53', 'retrieved', '78557DAE3A62C2C6E7723C5BEF21B723C4D692AF81A54F93131410D7CD722BD6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
