VALUES ('doc-14-nist-sp-800-53-p443-7', 'doc-14-nist-sp-800-53', '', 443, 'security category [OMB A-130] The characterization of information or an information system based on an assessment of the potential impact that a loss of confidentiality, integrity, or availability of such information or information system would have on agency operations, agency assets, individuals, other organizations, and the Nation.', 'kb-doc-14-nist-sp-800-53-p443-7', 0, 47, '14-nist-sp-800-53', 'retrieved', 'A27054FADB4155FF45BB1F02D4A5E157812652593DAC04BA4ABE99FF2E78F0BC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
