VALUES ('doc-14-nist-sp-800-53-p443-8', 'doc-14-nist-sp-800-53', '', 443, 'security control [OMB A-130] The safeguards or countermeasures prescribed for an information system or an organization to protect the confidentiality, integrity, and availability of the system and its information.', 'kb-doc-14-nist-sp-800-53-p443-8', 0, 29, '14-nist-sp-800-53', 'retrieved', '1AE69CA9EA97F219B202E654B9A055E25D684A55D1250A9E68F8EA4F51638243', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
