VALUES ('doc-14-nist-sp-800-53-p443-9', 'doc-14-nist-sp-800-53', '', 443, 'security control baseline [OMB A-130] The set of minimum security controls defined for a low-impact, moderate-impact, or high-impact information system.', 'kb-doc-14-nist-sp-800-53-p443-9', 0, 20, '14-nist-sp-800-53', 'retrieved', '57E5437552D635EFDFCAE405CD93B0311E8579BADC2D9CB97ADCE0E0DA47D3EE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
