VALUES ('doc-14-nist-sp-800-53-p443-10', 'doc-14-nist-sp-800-53', '', 443, 'security domain [CNSSI 4009] A domain that implements a security policy and is administered by a single authority.', 'kb-doc-14-nist-sp-800-53-p443-10', 0, 18, '14-nist-sp-800-53', 'retrieved', '2B3BC0390C25277783D92998E19C786066163CD536B05BCAEC59ABF157008272', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
