VALUES ('doc-14-nist-sp-800-53-p444-6', 'doc-14-nist-sp-800-53', '', 444, 'security marking The means used to associate a set of security attributes with objects in a human-readable form in order to enable organizational, process-based enforcement of information security policies.', 'kb-doc-14-nist-sp-800-53-p444-6', 0, 29, '14-nist-sp-800-53', 'retrieved', '0747B1E9E6A0AC1AE25F98DCA19840D46D84C0C86C8EAC8317DDCB9173C8D1ED', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
