VALUES ('doc-14-nist-sp-800-53-p445-2', 'doc-14-nist-sp-800-53', '', 445, 'security requirement [FIPS 200, Adapted] A requirement levied on an information system or an organization that is derived from applicable laws, executive orders, directives, regulations, policies, standards, procedures, or mission/business needs to ensure the confidentiality, integrity, and availability of information that is being processed, stored, or transmitted.', 'kb-doc-14-nist-sp-800-53-p445-2', 0, 47, '14-nist-sp-800-53', 'retrieved', '5686A9CD18390D15C03B3C496BAA21DC54262C286554E5F433450AFF49BDAC4E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
