VALUES ('doc-14-nist-sp-800-53-p445-3', 'doc-14-nist-sp-800-53', '', 445, 'Note: Security requirements can be used in a variety of contexts from high- level policy-related activities to low-level implementation-related activities in system development and engineering disciplines.', 'kb-doc-14-nist-sp-800-53-p445-3', 0, 26, '14-nist-sp-800-53', 'retrieved', 'DAF8FBFAC381CFEEC006DB939E380022EA3434B08C6DA50FAFEF14210EF9F862', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
