VALUES ('doc-14-nist-sp-800-53-p445-4', 'doc-14-nist-sp-800-53', '', 445, 'security service [SP 800-160-1] A security capability or function provided by an entity that supports one or more security objectives.', 'kb-doc-14-nist-sp-800-53-p445-4', 0, 20, '14-nist-sp-800-53', 'retrieved', '65F913065AA3E8AB5A13CDB0E2D4A4BCB26FAB958DC4D3915554BEF929F3269E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
