VALUES ('doc-14-nist-sp-800-53-p445-5', 'doc-14-nist-sp-800-53', '', 445, 'security-relevant information Information within the system that can potentially impact the operation of security functions or the provision of security services in a manner that could result in failure to enforce the system security policy or maintain isolation of code and data.', 'kb-doc-14-nist-sp-800-53-p445-5', 0, 42, '14-nist-sp-800-53', 'retrieved', '5119AD88A3EAD02D82B773CB69CD09CBA51386148D2F2B5797458CE15A5E1CE5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
