VALUES ('doc-14-nist-sp-800-53-p445-6', 'doc-14-nist-sp-800-53', '', 445, 'selection operation A control parameter that allows an organization to select a value from a list of predefined values provided as part of the control or control enhancement (e.g., selecting to either restrict an action or prohibit an action).', 'kb-doc-14-nist-sp-800-53-p445-6', 0, 39, '14-nist-sp-800-53', 'retrieved', 'D3531893BFDB52F59DA4D21DC811D02EBCBE1180B72435550AC50522F8B36F3E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
