VALUES ('doc-14-nist-sp-800-53-p445-10', 'doc-14-nist-sp-800-53', '', 445, 'Note: Organizations subordinate to federal agencies may use the term senior information security officer or chief information security officer to denote individuals who fill positions with similar responsibilities to senior agency information security officers.', 'kb-doc-14-nist-sp-800-53-p445-10', 0, 34, '14-nist-sp-800-53', 'retrieved', '2299367771AD782E10BCA0CBFF4E7B4C80BF09943BF2472AAA3FB635F225FF07', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
