VALUES ('doc-14-nist-sp-800-53-p445-13', 'doc-14-nist-sp-800-53', '', 445, 'sensitive compartmented information [CNSSI 4009] Classified information concerning or derived from intelligence sources, methods, or analytical processes, which is required to be handled within formal access control systems established by the Director of National Intelligence.', 'kb-doc-14-nist-sp-800-53-p445-13', 0, 35, '14-nist-sp-800-53', 'retrieved', 'D2211AEE05A9AD46D17C7A63F8C7A96BFA2AC3281E99ABAF19473B63C1DA54C8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
