VALUES ('doc-14-nist-sp-800-53-p446-2', 'doc-14-nist-sp-800-53', '', 446, 'service-oriented architecture A set of principles and methodologies for designing and developing software in the form of interoperable services. These services are well-defined business functions that are built as software components (i.e., discrete pieces of code and/or data structures) that can be reused for different purposes.', 'kb-doc-14-nist-sp-800-53-p446-2', 0, 46, '14-nist-sp-800-53', 'retrieved', 'BF6E09F8934ADF74B8A1AD23CC0B7EFEBFE5358B9581E5AD9AA15F545E6EDDCD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
