VALUES ('doc-14-nist-sp-800-53-p446-3', 'doc-14-nist-sp-800-53', '', 446, 'shared control A security or privacy control that is implemented for an information system in part as a common control and in part as a system-specific control. See hybrid control.', 'kb-doc-14-nist-sp-800-53-p446-3', 0, 30, '14-nist-sp-800-53', 'retrieved', 'E6B7736ACFFA125317C96B9C2632355A1FA19100FB8CBBF13E6119CF47079C26', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
