VALUES ('doc-14-nist-sp-800-53-p446-7', 'doc-14-nist-sp-800-53', '', 446, 'split tunneling The process of allowing a remote user or device to establish a non-remote connection with a system and simultaneously communicate via some other connection to a resource in an external network. This method of network access enables a user to access remote devices, and simultaneously, access uncontrolled networks.', 'kb-doc-14-nist-sp-800-53-p446-7', 0, 50, '14-nist-sp-800-53', 'retrieved', '1382E6C52C24EB3E009E0FCED77F233485831C2681C277D8956BB2B652B9507A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
