VALUES ('doc-14-nist-sp-800-53-p446-12', 'doc-14-nist-sp-800-53', '', 446, 'This includes all suppliers in the supply chain, developers or manufacturers of systems, system components, or system services; systems integrators; vendors; product resellers; and third party partners.', 'kb-doc-14-nist-sp-800-53-p446-12', 0, 27, '14-nist-sp-800-53', 'retrieved', '72F99E6A7F7CC42C03141A3649F50BA183C33EF63E6B166A3522CA4C3DBC26F5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
