VALUES ('doc-14-nist-sp-800-53-p446-14', 'doc-14-nist-sp-800-53', '', 446, 'Linked set of resources and processes between and among multiple tiers of organizations, each of which is an acquirer, that begins with the sourcing of products and services and extends through their life cycle.', 'kb-doc-14-nist-sp-800-53-p446-14', 0, 34, '14-nist-sp-800-53', 'retrieved', '45236837D56517ABF556E90D4635AD7CD63B153B172F4AF7E56D5B2AB63FF102', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
