VALUES ('doc-14-nist-sp-800-53-p447-2', 'doc-14-nist-sp-800-53', '', 447, 'supply chain element Organizations, entities, or tools employed for the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of systems and system components.', 'kb-doc-14-nist-sp-800-53-p447-2', 0, 28, '14-nist-sp-800-53', 'retrieved', '4AA8DF605A9B2650A6596E70D90E63EB97699C7163616BF16CE0A8A912D3A957', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
