INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p447-3', 'doc-14-nist-sp-800-53', '', 447, 'supply chain risk The potential for harm or compromise that arises as a result of security risks from suppliers, their supply chains, and their products or services. Supply chain risks include exposures, threats, and vulnerabilities associated with the products and services traversing the supply chain as well as the exposures, threats, and vulnerabilities to the supply chain.', 'kb-doc-14-nist-sp-800-53-p447-3', 0, 57, '14-nist-sp-800-53', 'retrieved', '015F6AD57CA01D9E837711F3C8A974FCCEAF5A8258A98EC90E3515FADB3B92DD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
