VALUES ('doc-14-nist-sp-800-53-p447-4', 'doc-14-nist-sp-800-53', '', 447, 'supply chain risk assessment A systematic examination of supply chain risks, likelihoods of their occurrence, and potential impacts.', 'kb-doc-14-nist-sp-800-53-p447-4', 0, 18, '14-nist-sp-800-53', 'retrieved', '3FD6F825BE3ED0AF36A95947097040557ADBCDE37F6329BED650155BD12351B4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
