VALUES ('doc-14-nist-sp-800-53-p447-6', 'doc-14-nist-sp-800-53', '', 447, 'A systematic process for managing cyber supply chain risk exposures, threats, and vulnerabilities throughout the supply chain and developing risk response strategies to the risks presented by the supplier, the supplied products and services, or the supply chain.', 'kb-doc-14-nist-sp-800-53-p447-6', 0, 38, '14-nist-sp-800-53', 'retrieved', '5DFAF7F4F85898006205EC51C83058D19A239B01227D7771CBFCEEF3B5317E83', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
