VALUES ('doc-14-nist-sp-800-53-p447-8', 'doc-14-nist-sp-800-53', '', 447, '[ISO 15288] Any organized assembly of resources and procedures united and regulated by interaction or interdependence to accomplish a set of specific functions.', 'kb-doc-14-nist-sp-800-53-p447-8', 0, 23, '14-nist-sp-800-53', 'retrieved', 'F961DC6420C3FFAAA91CD288D29C303267972C359937D4809E6A2DB8B9688517', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
