VALUES ('doc-14-nist-sp-800-53-p447-9', 'doc-14-nist-sp-800-53', '', 447, 'Note: Systems also include specialized systems such as industrial control systems, telephone switching and private branch exchange (PBX) systems, and environmental control systems.', 'kb-doc-14-nist-sp-800-53-p447-9', 0, 23, '14-nist-sp-800-53', 'retrieved', 'E0D860C985601D6B120A69B884E9CE478F7321714A14E31624773E7CCE1306B9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
