VALUES ('doc-14-nist-sp-800-53-p447-10', 'doc-14-nist-sp-800-53', '', 447, 'Combination of interacting elements organized to achieve one or more stated purposes.', 'kb-doc-14-nist-sp-800-53-p447-10', 0, 12, '14-nist-sp-800-53', 'retrieved', 'AF12337120CB96F66DE901C7921F43B1EE748EDEC3DED499EBBB967274916AFF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
