INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p447-11', 'doc-14-nist-sp-800-53', '', 447, 'Note 1: There are many types of systems. Examples include: general and special-purpose information systems; command, control, and communication systems; crypto modules; central processing unit and graphics processor boards; industrial control systems; flight control systems; weapons, targeting, and fire control systems; medical devices and treatment systems; financial, banking, and merchandising transaction systems; and social networking systems.', 'kb-doc-14-nist-sp-800-53-p447-11', 0, 56, '14-nist-sp-800-53', 'retrieved', '200CC4C2180BD0AE2C1C835BA8AB3C72AE08A5D4720F349E956D08B29C35CADF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
