VALUES ('doc-14-nist-sp-800-53-p447-12', 'doc-14-nist-sp-800-53', '', 447, 'Note 2: The interacting elements in the definition of system include hardware, software, data, humans, processes, facilities, materials, and naturally occurring physical entities.', 'kb-doc-14-nist-sp-800-53-p447-12', 0, 23, '14-nist-sp-800-53', 'retrieved', '4E52858A566BF201D83BCCF82798AE8B554467D8568ABE031FA22A67159A546C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
