VALUES ('doc-14-nist-sp-800-53-p447-14', 'doc-14-nist-sp-800-53', '', 447, 'system component [SP 800-128] A discrete identifiable information technology asset that represents a building block of a system and may include hardware, software, and firmware.', 'kb-doc-14-nist-sp-800-53-p447-14', 0, 25, '14-nist-sp-800-53', 'retrieved', 'AD4F0E4090FB184A47FD345728777FCD3FC7B331A8A9E6CC9E2AFEF9F07CC161', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
