VALUES ('doc-14-nist-sp-800-53-p448-5', 'doc-14-nist-sp-800-53', '', 448, 'system service A capability provided by a system that facilitates information processing, storage, or transmission.', 'kb-doc-14-nist-sp-800-53-p448-5', 0, 15, '14-nist-sp-800-53', 'retrieved', 'DFD4C8989E26F02C4AA56F84C7270E1DCDB9E1B811430DFBD894A993F76A13B0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
