INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p448-6', 'doc-14-nist-sp-800-53', '', 448, 'system-related security risk [SP 800-30] Risk that arises through the loss of confidentiality, integrity, or availability of information or systems and that considers impacts to the organization (including assets, mission, functions, image, or reputation), individuals, other organizations, and the Nation.', 'kb-doc-14-nist-sp-800-53-p448-6', 0, 40, '14-nist-sp-800-53', 'retrieved', '832E910D286C97021057116CFB6F7D17200DAA3E6314A548ED23F7E3AAA85033', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
