INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p448-8', 'doc-14-nist-sp-800-53', '', 448, 'system-specific control [OMB A-130] A security or privacy control for an information system that is implemented at the system level and is not inherited by any other information system.', 'kb-doc-14-nist-sp-800-53-p448-8', 0, 29, '14-nist-sp-800-53', 'retrieved', '63BE299FA4C29945EEA7218DBD8CEA7E91CE59ABE5585172129545BBFD6FBB1C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
