INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p448-9', 'doc-14-nist-sp-800-53', '', 448, 'systems engineering [SP 800-160-1] An engineering discipline whose responsibility is creating and executing an interdisciplinary process to ensure that the customer and all other stakeholder needs are satisfied in a high- quality, trustworthy, cost-efficient, and schedule-compliant manner throughout a system’s entire life cycle.', 'kb-doc-14-nist-sp-800-53-p448-9', 0, 43, '14-nist-sp-800-53', 'retrieved', '3605660453DE1DDD42D3DDCA5DD20CD6926680E2B43B74B36A313E3A5FAE983C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p448-10', 'doc-14-nist-sp-800-53', '', 448, 'systems security engineering [SP 800-160-1] A specialty engineering field strongly related to systems engineering. It applies scientific, engineering, and information assurance principles to deliver trustworthy systems that satisfy stakeholder requirements within their established risk tolerance.', 'kb-doc-14-nist-sp-800-53-p448-10', 0, 35, '14-nist-sp-800-53', 'retrieved', 'E6A91A0D2F5C6F6D9EFF4437B3FA53F37D1706819786D3845990CB1A0EE7A092', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
