VALUES ('doc-14-nist-sp-800-53-p448-11', 'doc-14-nist-sp-800-53', '', 448, 'tailored control baseline A set of controls that result from the application of tailoring guidance to a control baseline. See tailoring.', 'kb-doc-14-nist-sp-800-53-p448-11', 0, 21, '14-nist-sp-800-53', 'retrieved', '2CDE628A22A4A5BA1B3FD0601AF277B34BF72262E5F2668F79D5EC291F15ACD4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
