INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p448-12', 'doc-14-nist-sp-800-53', '', 448, 'tailoring The process by which security control baselines are modified by: identifying and designating common controls, applying scoping considerations on the applicability and implementation of baseline controls, selecting compensating security controls, assigning specific values to organization-defined security control parameters, supplementing baselines with additional security controls or control enhancements, and providing additional specification information for control implementation.', 'kb-doc-14-nist-sp-800-53-p448-12', 0, 56, '14-nist-sp-800-53', 'retrieved', '5E694F20B4C31715C2FE5C78654329EB7CE8E7E8D9DC40CC30F50D42F33D23F4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p448-13', 'doc-14-nist-sp-800-53', '', 448, 'tampering [CNSSI 4009] An intentional but unauthorized act resulting in the modification of a system, components of systems, its intended behavior, or data.', 'kb-doc-14-nist-sp-800-53-p448-13', 0, 23, '14-nist-sp-800-53', 'retrieved', '40D57B857CD196ECEA24FCB985406853B2BA288369B69B76CA7C6B72D56F281B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
