INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-2', 'doc-14-nist-sp-800-53', '', 449, 'threat [SP 800-30] Any circumstance or event with the potential to adversely impact organizational operations, organizational assets, individuals, other organizations, or the Nation through a system via unauthorized access, destruction, disclosure, modification of information, and/or denial of service.', 'kb-doc-14-nist-sp-800-53-p449-2', 0, 38, '14-nist-sp-800-53', 'retrieved', '2919D2C56E05EE6417BC564ABF19079E2544E8CEE5E737E62C5533495BBEB1B3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
