VALUES ('doc-14-nist-sp-800-53-p449-3', 'doc-14-nist-sp-800-53', '', 449, 'threat assessment [CNSSI 4009] Formal description and evaluation of threat to an information system.', 'kb-doc-14-nist-sp-800-53-p449-3', 0, 14, '14-nist-sp-800-53', 'retrieved', '08A05ABB56D2D13C5BFBB5BD4A43FCF2D0727678790558090B10EE5EA54E245F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
