INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-5', 'doc-14-nist-sp-800-53', '', 449, 'threat source [FIPS 200] A form of risk assessment that models aspects of the attack and defense sides of a logical entity, such as a piece of data, an application, a host, a system, or an environment.', 'kb-doc-14-nist-sp-800-53-p449-5', 0, 37, '14-nist-sp-800-53', 'retrieved', '0819A8BAFC2FE059FBA1DD20D984DC15BB8B72ED0F851C92133AA3C56703D439', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
