INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-6', 'doc-14-nist-sp-800-53', '', 449, 'The intent and method targeted at the intentional exploitation of a vulnerability or a situation and method that may accidentally trigger a vulnerability. See threat agent.', 'kb-doc-14-nist-sp-800-53-p449-6', 0, 26, '14-nist-sp-800-53', 'retrieved', '9723349CB206CCA619E0E3583122A16AB531DD81088E95040E5530F2DF829B74', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
