INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-7', 'doc-14-nist-sp-800-53', '', 449, 'transmission [CNSSI 4009] The state that exists when information is being electronically sent from one location to one or more other locations.', 'kb-doc-14-nist-sp-800-53-p449-7', 0, 22, '14-nist-sp-800-53', 'retrieved', 'D0868B748B322851A08D3FBDFE10C0DCAB460FE2B542608B6638AE930D8B4FEA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
