INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-8', 'doc-14-nist-sp-800-53', '', 449, 'trusted path A mechanism by which a user (through an input device) can communicate directly with the security functions of the system with the necessary confidence to support the system security policy. This mechanism can only be activated by the user or the security functions of the system and cannot be imitated by untrusted software.', 'kb-doc-14-nist-sp-800-53-p449-8', 0, 55, '14-nist-sp-800-53', 'retrieved', '28CE547DF2CA588CADFF76AA28B6082BBD1C559EA20F12748CA2146003AED1CC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
