INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-9', 'doc-14-nist-sp-800-53', '', 449, 'trustworthiness [CNSSI 4009] The attribute of a person or enterprise that provides confidence to others of the qualifications, capabilities, and reliability of that entity to perform specific tasks and fulfill assigned responsibilities.', 'kb-doc-14-nist-sp-800-53-p449-9', 0, 32, '14-nist-sp-800-53', 'retrieved', '054D24EB4FD4F97FE3C11E7DAEE7BC0305034B2D676C04D585D82651BA9F9AE1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p449-10', 'doc-14-nist-sp-800-53', '', 449, 'trustworthiness (system) The degree to which an information system (including the information technology components that are used to build the system) can be expected to preserve the confidentiality, integrity, and availability of the information being processed, stored, or transmitted by the system across the full range of threats. A trustworthy information system is believed to operate within defined levels of risk despite the environmental disruptions, human errors, structural failures, and purposeful attacks that are expected to occur in its environment of operation.', 'kb-doc-14-nist-sp-800-53-p449-10', 0, 82, '14-nist-sp-800-53', 'retrieved', '2944292185585D369336CF5575A2ABDA0F1665051E37BE6F5F6AD2185F9CB60F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
