VALUES ('doc-14-nist-sp-800-53-p449-12', 'doc-14-nist-sp-800-53', '', 449, 'Individual, or (system) process acting on behalf of an individual, authorized to access a system.', 'kb-doc-14-nist-sp-800-53-p449-12', 0, 15, '14-nist-sp-800-53', 'retrieved', '5C690EED8BAF81750A1BFCB36B5115429F68DC5911BA8F4BAADAD07DF53F72F4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
