VALUES ('doc-14-nist-sp-800-53-p449-14', 'doc-14-nist-sp-800-53', '', 449, 'virtual private network [CNSSI 4009] Protected information system link utilizing tunneling, security controls, and endpoint address translation giving the impression of a dedicated line.', 'kb-doc-14-nist-sp-800-53-p449-14', 0, 24, '14-nist-sp-800-53', 'retrieved', 'E549C51125AF4F1A9E4171A261F0D0358CF5420B0379F7279D0FDF59F47BA050', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
