INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-2', 'doc-14-nist-sp-800-53', '', 455, 'APPENDIX C CONTROL SUMMARIES IMPLEMENTATION, WITHDRAWAL, AND ASSURANCE DESIGNATIONS Tables C-1 through C-20 provide a summary of the security and privacy controls and control enhancements in Chapter Three. Each table focuses on a different control family.', 'kb-doc-14-nist-sp-800-53-p455-2', 0, 36, '14-nist-sp-800-53', 'retrieved', '49AE8523B4D8421684C46B9BD9B32D6CD8D7AC640029BB932B440E95EBCE8084', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-3', 'doc-14-nist-sp-800-53', '', 455, '• A control or control enhancement that has been withdrawn from the control catalog is indicated by a “W” and an explanation of the control or control enhancement disposition in light gray text.', 'kb-doc-14-nist-sp-800-53-p455-3', 0, 33, '14-nist-sp-800-53', 'retrieved', 'A41D77E76EB33FEF554569E17CC3FB0D96BB2DFC81A0F16107AAE46CE54E490D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-4', 'doc-14-nist-sp-800-53', '', 455, '• A control or control enhancement that is typically implemented by an information system through technical means is indicated by an “S” in the implemented by column.', 'kb-doc-14-nist-sp-800-53-p455-4', 0, 27, '14-nist-sp-800-53', 'retrieved', 'A93D5E86AD191001047EE08D67F38C3D8B165F7222FF650C7D14D5CA45516492', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-5', 'doc-14-nist-sp-800-53', '', 455, '• A control or control enhancement that is typically implemented by an organization (i.e., by an individual through nontechnical means) is indicated by an “O” in the implemented by column.35 • A control or control enhancement that can be implemented by an organization, a system, or a combination of the two is indicated by an “O/S.” • A control or control enhancement marked with a “√” in the assurance column indicates the control or control enhancement contributes to the grounds for confidence that a security or privacy claim has been or will be achieved.36 Each control and control enhancement in Tables C-1 through C-20 is hyperlinked to the text for that control and control enhancement in Chapter Three.', 'kb-doc-14-nist-sp-800-53-p455-5', 0, 118, '14-nist-sp-800-53', 'retrieved', '5F9D52E8E26C56F6A1247452FDF22BD443DDDCBFB71AB72FC5E3BD94357E3946', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-6', 'doc-14-nist-sp-800-53', '', 455, 'Families of controls contain base controls and control enhancements, which are directly related to their base controls. Control enhancements either add functionality or specificity to a base control or increase the strength of a base control. In both cases, control enhancements are used in systems and environments of operation that require greater protection than provided by the base control. This increased protection is required due to the potential adverse organizational or individual impacts or when organizations require additions to the base control functionality or assurance based on organizational assessments of risk. The use of control enhancements always requires the use of the base control.', 'kb-doc-14-nist-sp-800-53-p455-6', 0, 104, '14-nist-sp-800-53', 'retrieved', '7A13E15AB0A24E67B95C561CE9E7477D3164D2F9F1D4D17EF0CF32EA8129DE38', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-7', 'doc-14-nist-sp-800-53', '', 455, 'The families are arranged in alphabetical order, while the controls and control enhancements within each family are arranged in numerical order. The alphabetical or numerical order of the families, controls, and control enhancements does not imply any type of prioritization, level of importance, or order in which the controls or control enhancements are to be implemented.', 'kb-doc-14-nist-sp-800-53-p455-7', 0, 56, '14-nist-sp-800-53', 'retrieved', '2AFB34FCEF4CB04E36171EAB40627EDC006367784D92C26D2CFE7D6C0F48C23F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-8', 'doc-14-nist-sp-800-53', '', 455, '35 The indication that a certain control or control enhancement is implemented by a system or by an organization in Tables C-1 through C-20 is notional. Organizations have the flexibility to implement their selected controls and control enhancements in the most cost-effective and efficient manner while simultaneously complying with the intent of the controls or control enhancements. In certain situations, a control or control enhancement may be implemented by the system, the organization, or a combination of the two entities.', 'kb-doc-14-nist-sp-800-53-p455-8', 0, 80, '14-nist-sp-800-53', 'retrieved', '56D8BCD6C07E18EB0DF681E62CA371F9813FEF894C8DC1E9A90DC8B8327F9D83', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p455-9', 'doc-14-nist-sp-800-53', '', 455, '36 Assurance is a critical aspect in determining the trustworthiness of systems. Assurance is the measure of confidence that the security and privacy functions, features, practices, policies, procedures, mechanisms, and architecture of organizational systems accurately mediate and enforce established security and privacy policies.', 'kb-doc-14-nist-sp-800-53-p455-9', 0, 43, '14-nist-sp-800-53', 'retrieved', 'F604F28BB8E0FB415D24DD98BFFD17D28AB08FBC545C43AA53B9D2D40CC56663', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
